/* DAWAH X — ahmad, অধ্যায় 19 · খণ্ড 19 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][19]=[[3601,3601,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏سَيَلِي أَمْرَكُمْ ‏ ‏مِنْ بَعْدِي رِجَالٌ يُطْفِئُونَ السُّنَّةَ وَيُحْدِثُونَ بِدْعَةً وَيُؤَخِّرُونَ الصَّلَاةَ عَنْ مَوَاقِيتِهَا قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏يَا رَسُولَ اللَّهِ كَيْفَ بِي إِذَا أَدْرَكْتُهُمْ قَالَ لَيْسَ يَا ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏ ‏طَاعَةٌ لِمَنْ عَصَى اللَّهَ قَالَهَا ثَلَاثَ مَرَّاتٍ ‏ ‏و سَمِعْت ‏ ‏أَنَا مِنْ ‏ ‏مُحَمَّدِ بْنِ الصَّبَّاحِ ‏ ‏مِثْلَهُ ‏","","",""],[3602,3602,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏وَحَمْزَةَ ‏ ‏ابْنَيْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْكُلُ اللَّحْمَ ثُمَّ يَقُومُ إِلَى الصَّلَاةِ وَلَا يَمَسُّ مَاءً ‏","","",""],[3603,3603,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ اللَّحْمَ ثُمَّ يَقُومُ إِلَى الصَّلَاةِ فَمَا يَمَسُّ قَطْرَةَ مَاءٍ ‏","","",""],[3604,3604,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ لَحْمًا ثُمَّ قَامَ إِلَى الصَّلَاةِ وَلَمْ يَمَسَّ مَاءً ‏","","",""],[3605,3605,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏انْطَلَقَ ‏ ‏سَعْدُ بْنُ مُعَاذٍ ‏ ‏مُعْتَمِرًا فَنَزَلَ عَلَى ‏ ‏صَفْوَانَ بْنِ أُمَيَّةَ بْنِ خَلَفٍ ‏ ‏وَكَانَ ‏ ‏أُمَيَّةُ ‏ ‏إِذَا انْطَلَقَ إِلَى ‏ ‏الشَّامِ ‏ ‏فَمَرَّ ‏ ‏بِالْمَدِينَةِ ‏ ‏نَزَلَ عَلَى ‏ ‏سَعْدٍ ‏ ‏فَقَالَ ‏ ‏أُمَيَّةُ ‏ ‏لِسَعْدٍ ‏ ‏انْتَظِرْ حَتَّى إِذَا انْتَصَفَ النَّهَارُ وَغَفَلَ النَّاسُ انْطَلَقْتَ فَطُفْتَ فَبَيْنَمَا ‏ ‏سَعْدٌ ‏ ‏يَطُوفُ إِذْ أَتَاهُ ‏ ‏أَبُو جَهْلٍ ‏ ‏فَقَالَ مَنْ هَذَا يَطُوفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏آمِنًا قَالَ ‏ ‏سَعْدٌ ‏ ‏أَنَا ‏ ‏سَعْدٌ ‏ ‏فَقَالَ ‏ ‏أَبُو جَهْلٍ ‏ ‏تَطُوفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏آمِنًا وَقَدْ آوَيْتُمْ ‏ ‏مُحَمَّدًا ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏فَتَلَاحَيَا ‏ ‏فَقَالَ ‏ ‏أُمَيَّةُ ‏ ‏لِسَعْدٍ ‏ ‏لَا تَرْفَعَنَّ صَوْتَكَ عَلَى ‏ ‏أَبِي الْحَكَمِ ‏ ‏فَإِنَّهُ سَيِّدُ أَهْلِ ‏ ‏الْوَادِي ‏ ‏فَقَالَ لَهُ ‏ ‏سَعْدٌ ‏ ‏وَاللَّهِ إِنْ مَنَعْتَنِي أَنْ أَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏لَأَقْطَعَنَّ إِلَيْكَ مَتْجَرَكَ إِلَى ‏ ‏الشَّأْمِ ‏ ‏فَجَعَلَ ‏ ‏أُمَيَّةُ ‏ ‏يَقُولُ لَا تَرْفَعَنَّ صَوْتَكَ عَلَى ‏ ‏أَبِي الْحَكَمِ ‏ ‏وَجَعَلَ يُمْسِكُهُ فَغَضِبَ ‏ ‏سَعْدٌ ‏ ‏فَقَالَ دَعْنَا مِنْكَ ‏ ‏فَإِنِّي سَمِعْتُ ‏ ‏مُحَمَّدًا ‏ ‏يَزْعُمُ أَنَّهُ قَاتِلُكَ قَالَ إِيَّايَ قَالَ نَعَمْ قَالَ وَاللَّهِ مَا يَكْذِبُ ‏ ‏مُحَمَّدٌ ‏ ‏فَلَمَّا خَرَجُوا رَجَعَ إِلَى امْرَأَتِهِ فَقَالَ أَمَا عَلِمْتِ مَا قَالَ لِي الْيَثْرِبِيُّ فَأَخْبَرَهَا فَلَمَّا جَاءَ ‏ ‏الصَّرِيخُ ‏ ‏وَخَرَجُوا إِلَى ‏ ‏بَدْرٍ ‏ ‏قَالَتْ امْرَأَتُهُ أَمَا تَذْكُرُ مَا قَالَ أَخُوكَ الْيَثْرِبِيُّ فَأَرَادَ أَنْ لَا يَخْرُجَ فَقَالَ لَهُ ‏ ‏أَبُو جَهْلٍ ‏ ‏إِنَّكَ مِنْ أَشْرَافِ ‏ ‏الْوَادِي ‏ ‏فَسِرْ مَعَنَا يَوْمًا أَوْ يَوْمَيْنِ فَسَارَ مَعَهُمْ فَقَتَلَهُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏انْطَلَقَ ‏ ‏سَعْدُ بْنُ مُعَاذٍ ‏ ‏مُعْتَمِرًا عَلَى ‏ ‏أُمَيَّةَ بْنِ خَلَفِ بْنِ صَفْوَانَ ‏ ‏وَكَانَ ‏ ‏أُمَيَّةُ ‏ ‏إِذَا انْطَلَقَ إِلَى ‏ ‏الشَّامِ ‏ ‏وَمَرَّ ‏ ‏بِالْمَدِينَةِ ‏ ‏نَزَلَ عَلَى ‏ ‏سَعْدٍ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ فَرَجَعَ إِلَى ‏ ‏أُمِّ صَفْوَانَ ‏ ‏فَقَالَ أَمَا تَعْلَمِي مَا قَالَ أَخِي الْيَثْرِبِيُّ قَالَتْ وَمَا قَالَ قَالَ زَعَمَ أَنَّهُ سَمِعَ ‏ ‏مُحَمَّدًا ‏ ‏يَزْعُمُ أَنَّهُ قَاتِلِي قَالَتْ فَوَاللَّهِ مَا يَكْذِبُ ‏ ‏مُحَمَّدٌ ‏ ‏فَلَمَّا خَرَجُوا إِلَى ‏ ‏بَدْرٍ ‏ ‏وَسَاقَهُ ‏","","",""],[3606,3606,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّي ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ إِذَا نَامَ وَضَعَ يَمِينَهُ تَحْتَ خَدِّهِ وَقَالَ ‏ ‏اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَجْمَعُ عِبَادَكَ ‏","","",""],[3607,3607,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ كَانَ فِي الْمَسْجِدِ يَدْعُو فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَدْعُو فَقَالَ ‏ ‏سَلْ ‏ ‏تُعْطَهْ وَهُوَ يَقُولُ اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ وَنَعِيمًا لَا ‏ ‏يَنْفَدُ ‏ ‏وَمُرَافَقَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَعْلَى غُرَفِ الْجَنَّةِ جَنَّةِ الْخُلْدِ ‏","","",""],[3608,3608,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فِي الْيَقَظَةِ فَإِنَّ الشَّيْطَانَ لَا يَتَمَثَّلُ عَلَى صُورَتِي ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[3609,3609,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ ‏ ‏وُلَاةً ‏ ‏وَإِنَّ ‏ ‏وَلِيِّي ‏ ‏مِنْهُمْ أَبِي وَخَلِيلُ رَبِّي ‏ ‏إِبْرَاهِيمُ ‏ ‏قَالَ ثُمَّ قَرَأَ ‏ { ‏إِنَّ أَوْلَى النَّاسِ ‏ ‏بِإِبْرَاهِيمَ ‏ } ‏إِلَى آخِرِ ‏ ‏الْآيَةَ ‏","","",""],[3610,3610,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَمُؤَمَّلٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي ‏ ‏قُبَّةٍ ‏ ‏حَمْرَاءَ ‏ ‏قَالَ ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏مِنْ ‏ ‏أَدَمٍ ‏ ‏فِي نَحْوٍ مِنْ أَرْبَعِينَ رَجُلًا فَقَالَ ‏ ‏إِنَّكُمْ مَفْتُوحٌ عَلَيْكُمْ مَنْصُورُونَ وَمُصِيبُونَ فَمَنْ ‏ ‏أَدْرَكَ ‏ ‏ذَلِكَ مِنْكُمْ فَلْيَتَّقِ اللَّهَ وَلْيَأْمُرْ بِالْمَعْرُوفِ وَلْيَنْهَ عَنْ الْمُنْكَرِ وَلْيَصِلْ رَحِمَهُ مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ وَمَثَلُ الَّذِي يُعِينُ قَوْمَهُ عَلَى غَيْرِ الْحَقِّ كَمَثَلِ بَعِيرٍ ‏ ‏رُدِّيَ ‏ ‏فِي بِئْرٍ فَهُوَ يَنْزِعُ مِنْهَا بِذَنَبِهِ ‏","","",""],[3611,3611,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِيِه ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا وَقَدْ وُكِّلَ بِهِ قَرِينُهُ مِنْ الْجِنِّ وَقَرِينُهُ مِنْ الْمَلَائِكَةِ قَالُوا وَإِيَّاكَ يَا رَسُولَ اللَّهِ قَالَ وَإِيَّايَ لَكِنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَأَسْلَمَ فَلَا يَأْمُرُنِي إِلَّا بِخَيْرٍ ‏","","",""],[3612,3612,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا يَقْرَأُ ‏ ‏حم ‏ ‏الثَّلَاثِينَ ‏ ‏يَعْنِي ‏ ‏الْأَحْقَافَ ‏ ‏فَقَرَأَ حَرْفًا وَقَرَأَ رَجُلٌ آخَرُ حَرْفًا لَمْ يَقْرَأْهُ صَاحِبُهُ وَقَرَأْتُ أَحْرُفًا فَلَمْ يَقْرَأْهَا صَاحِبَيَّ فَانْطَلَقْنَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْنَاهُ فَقَالَ ‏ ‏لَا تَخْتَلِفُوا فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِاخْتِلَافِهِمْ ثُمَّ قَالَ انْظُرُوا أَقْرَأَكُمْ رَجُلًا فَخُذُوا بِقِرَاءَتِهِ ‏","","",""],[3613,3613,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏وَعَنْ ‏ ‏أَبِي سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْكَنُودِ ‏ ‏قَالَ ‏ ‏أَصَبْتُ ‏ ‏خَاتَمًا مِنْ ذَهَبٍ فِي بَعْضِ الْمَغَازِي فَلَبِسْتُهُ فَأَتَيْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَأَخَذَهُ فَوَضَعَهُ بَيْنَ لَحْيَيْهِ فَمَضَغَهُ وَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُتَخَتَّمَ بِخَاتَمِ الذَّهَبِ ‏ ‏أَوْ قَالَ بِحَلَقَةِ الذَّهَبِ ‏","","",""],[3614,3614,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سُورَةِ ‏ ‏النَّجْمِ ‏ ‏فَمَا بَقِيَ أَحَدٌ مِنْ الْقَوْمِ إِلَّا سَجَدَ إِلَّا شَيْخٌ أَخَذَ كَفًّا مِنْ حَصًى فَرَفَعَهُ إِلَى جَبْهَتِهِ وَقَالَ يَكْفِينِي هَذَا قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَلَقَدْ رَأَيْتُهُ قُتِلَ كَافِرًا ‏","","",""],[3615,3615,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَكْثَرْنَا الْحَدِيثَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ ثُمَّ ‏ ‏غَدَوْنَا ‏ ‏إِلَيْهِ فَقَالَ ‏ ‏عُرِضَتْ عَلَيَّ الْأَنْبِيَاءُ اللَّيْلَةَ بِأُمَمِهَا فَجَعَلَ النَّبِيُّ يَمُرُّ وَمَعَهُ الثَّلَاثَةُ وَالنَّبِيُّ وَمَعَهُ ‏ ‏الْعِصَابَةُ ‏ ‏وَالنَّبِيُّ وَمَعَهُ ‏ ‏النَّفَرُ ‏ ‏وَالنَّبِيُّ لَيْسَ مَعَهُ أَحَدٌ حَتَّى مَرَّ عَلَيَّ ‏ ‏مُوسَى ‏ ‏مَعَهُ ‏ ‏كَبْكَبَةٌ ‏ ‏مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَأَعْجَبُونِي فَقُلْتُ مَنْ هَؤُلَاءِ فَقِيلَ لِي هَذَا أَخُوكَ ‏ ‏مُوسَى ‏ ‏مَعَهُ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏قَالَ قُلْتُ فَأَيْنَ أُمَّتِي فَقِيلَ ‏ ‏لِيَ انْظُرْ عَنْ يَمِينِكَ فَنَظَرْتُ فَإِذَا ‏ ‏الظِّرَابُ ‏ ‏قَدْ سُدَّ بِوُجُوهِ الرِّجَالِ ثُمَّ قِيلَ ‏ ‏لِيَ انْظُرْ عَنْ يَسَارِكَ فَنَظَرْتُ فَإِذَا ‏ ‏الْأُفُقُ ‏ ‏قَدْ سُدَّ بِوُجُوهِ الرِّجَالِ فَقِيلَ لِي أَرَضِيتَ فَقُلْتُ رَضِيتُ يَا رَبِّ رَضِيتُ يَا رَبِّ قَالَ فَقِيلَ لِي إِنَّ مَعَ هَؤُلَاءِ سَبْعِينَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِدًا لَكُمْ أَبِي وَأُمِّي إِنْ اسْتَطَعْتُمْ أَنْ تَكُونُوا مِنْ السَّبْعِينَ الْأَلْفِ فَافْعَلُوا فَإِنْ قَصَّرْتُمْ فَكُونُوا مِنْ أَهْلِ ‏ ‏الظِّرَابِ ‏ ‏فَإِنْ قَصَّرْتُمْ فَكُونُوا مِنْ أَهْلِ ‏ ‏الْأُفُقِ ‏ ‏فَإِنِّي قَدْ رَأَيْتُ ثَمَّ نَاسًا يَتَهَاوَشُونَ فَقَامَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ ‏ ‏فَقَالَ ادْعُ اللَّهَ لِي يَا رَسُولَ اللَّهِ أَنْ يَجْعَلَنِي مِنْ السَّبْعِينَ فَدَعَا لَهُ فَقَامَ رَجُلٌ آخَرُ فَقَالَ ادْعُ اللَّهَ يَا رَسُولَ اللَّهِ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ قَدْ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏ ‏قَالَ ثُمَّ تَحَدَّثْنَا فَقُلْنَا مَنْ تَرَوْنَ هَؤُلَاءِ السَّبْعُونَ الْأَلْفُ قَوْمٌ وُلِدُوا فِي الْإِسْلَامِ لَمْ يُشْرِكُوا بِاللَّهِ شَيْئًا حَتَّى مَاتُوا فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هُمْ الَّذِينَ لَا ‏ ‏يَكْتَوُونَ ‏ ‏وَلَا ‏ ‏يَسْتَرْقُونَ ‏ ‏وَلَا ‏ ‏يَتَطَيَّرُونَ ‏ ‏وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ ‏","","",""],[3616,3616,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَلَمْ يَجِدُوا مَاءً فَأُتِيَ بِتَوْرٍ مِنْ مَاءٍ ‏ ‏فَوَضَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ يَدَهُ وَفَرَّجَ بَيْنَ أَصَابِعِهِ قَالَ فَرَأَيْتُ الْمَاءَ يَتَفَجَّرُ مِنْ بَيْنِ أَصَابِعِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ حَيَّ عَلَى الْوُضُوءِ وَالْبَرَكَةُ مِنْ اللَّهِ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏فَأَخْبَرَنِي ‏ ‏سَالِمُ بْنُ أَبِي الْجَعْدِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏كَمْ كَانَ النَّاسُ يَوْمَئِذٍ قَالَ كُنَّا أَلْفًا وَخَمْسَ مِائَةٍ ‏","","",""],[3617,3617,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ لِي أَنْ أَعْلَمَ إِذَا أَحْسَنْتُ وَإِذَا أَسَأْتُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَمِعْتَ جِيرَانَكَ يَقُولُونَ قَدْ أَحْسَنْتَ فَقَدْ أَحْسَنْتَ وَإِذَا سَمِعْتَهُمْ يَقُولُونَ قَدْ أَسَأْتَ فَقَدْ أَسَأْتَ ‏","","",""],[3618,3618,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَنْبَأَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَشَاهِدَيْهِ وَكَاتِبَهُ قَالَ وَقَالَ مَا ظَهَرَ فِي قَوْمٍ الرِّبَا وَالزِّنَا إِلَّا أَحَلُّوا بِأَنْفُسِهِمْ عِقَابَ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3619,3619,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي زَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَمْرِو بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ لَقِيَ الْجِنَّ فَقَالَ أَمَعَكَ مَاءٌ فَقُلْتُ لَا فَقَالَ مَا هَذَا فِي ‏ ‏الْإِدَاوَةِ ‏ ‏قُلْتُ نَبِيذٌ قَالَ ‏ ‏أَرِنِيهَا تَمْرَةٌ طَيِّبَةٌ وَمَاءٌ طَهُورٌ فَتَوَضَّأَ مِنْهَا ثُمَّ صَلَّى بِنَا ‏","","",""],[3620,3620,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ جَعَلَ لِلَّهِ نِدًّا جَعَلَهُ اللَّهُ فِي النَّارِ ‏ ‏و قَالَ ‏ ‏وَأُخْرَى أَقُولُهَا لَمْ أَسْمَعْهَا مِنْهُ مَنْ مَاتَ لَا يَجْعَلُ لِلَّهِ ‏ ‏نِدًّا ‏ ‏أَدْخَلَهُ اللَّهُ الْجَنَّةَ وَإِنَّ هَذِهِ الصَّلَوَاتِ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ مَا اجْتُنِبَ الْمَقْتَلُ ‏","","",""],[3621,3621,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ وَإِنِّي سَأُنَازَعُ رِجَالًا فَأُغْلَبُ عَلَيْهِمْ فَأَقُولُ يَا رَبِّ أَصْحَابِي فَيُقَالُ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[3622,3622,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ السَّلَامِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ فِي السَّفَرِ وَيُفْطِرُ وَيُصَلِّي رَكْعَتَيْنِ لَا يَدَعُهُمَا يَقُولُ لَا يَزِيدُ عَلَيْهِمَا ‏ ‏يَعْنِي الْفَرِيضَةَ ‏","","",""],[3623,3623,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَاصِمًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[3624,3624,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا ‏ ‏يَضْرِبُ ‏ ‏بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[3625,3625,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِقَوْمٍ يَتَخَلَّفُونَ عَنْ الْجُمُعَةِ لَقَدْ ‏ ‏هَمَمْتُ أَنْ آمُرَ رَجُلًا ‏ ‏يُصَلِّي بِالنَّاسِ ثُمَّ أُحَرِّقَ عَلَى رِجَالٍ يَتَخَلَّفُونَ عَنْ الْجُمُعَةِ بُيُوتَهُمْ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقُ ‏ ‏أَنَّهُ سَمِعَهُ مِنْ ‏ ‏أَبِي الْأَحْوَصِ ‏","","",""],[3626,3626,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَأَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ أَيَّامًا يُرْفَعُ فِيهِنَّ الْعِلْمُ وَيَنْزِلُ فِيهِنَّ الْجَهْلُ وَيَكْثُرُ فِيهِنَّ ‏ ‏الْهَرْجُ ‏ ‏قَالَ ‏ ‏وَالْهَرْجُ ‏ ‏الْقَتْلُ ‏","","",""],[3627,3627,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ ‏ ‏عَنْ ‏ ‏أَبِي عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ ‏ ‏وَمُحَقَّرَاتِ ‏ ‏الذُّنُوبِ فَإِنَّهُنَّ يَجْتَمِعْنَ عَلَى الرَّجُلِ حَتَّى يُهْلِكْنَهُ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَرَبَ لَهُنَّ مَثَلًا كَمَثَلِ قَوْمٍ نَزَلُوا أَرْضَ ‏ ‏فَلَاةٍ ‏ ‏فَحَضَرَ صَنِيعُ الْقَوْمِ فَجَعَلَ الرَّجُلُ يَنْطَلِقُ فَيَجِيءُ بِالْعُودِ ‏ ‏وَالرَّجُلُ يَجِيءُ بِالْعُودِ حَتَّى جَمَعُوا ‏ ‏سَوَادًا ‏ ‏فَأَجَّجُوا نَارًا وَأَنْضَجُوا مَا قَذَفُوا فِيهَا ‏","","",""],[3628,3628,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرِيَ الْأُمَمَ بِالْمَوْسِمِ فَرَاثَتْ عَلَيْهِ أُمَّتُهُ قَالَ ‏ ‏فَأُرِيتُ أُمَّتِي فَأَعْجَبَنِي كَثْرَتُهُمْ قَدْ مَلَئُوا السَّهْلَ وَالْجَبَلَ فَقِيلَ لِي إِنَّ مَعَ هَؤُلَاءِ سَبْعِينَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ هُمْ الَّذِينَ لَا ‏ ‏يَكْتَوُونَ ‏ ‏وَلَا يَسْتَرْقُونَ وَلَا ‏ ‏يَتَطَيَّرُونَ ‏ ‏وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ فَقَالَ ‏ ‏عُكَّاشَةُ ‏ ‏يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَدَعَا لَهُ ثُمَّ قَامَ ‏ ‏يَعْنِي آخَرُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مَعَهُمْ قَالَ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏","","",""],[3629,3629,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيلَ لَهُ كَيْفَ تَعْرِفُ مَنْ لَمْ يَرَكَ مِنْ أُمَّتِكَ فَقَالَ ‏ ‏إِنَّهُمْ ‏ ‏غُرٌّ ‏ ‏مُحَجَّلُونَ ‏ ‏بُلْقٌ ‏ ‏مِنْ آثَارِ الْوُضُوءِ ‏","","",""],[3630,3630,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ ثُلُثُ اللَّيْلِ الْبَاقِي يَهْبِطُ إِلَى السَّمَاءِ الدُّنْيَا ثُمَّ يَفْتَحُ أَبْوَابَ السَّمَاءِ ثُمَّ يَبْسُطُ يَدَهُ فَيَقُولُ هَلْ مِنْ سَائِلٍ يُعْطَى سُؤْلَهُ وَلَا يَزَالُ كَذَلِكَ حَتَّى يَسْطَعَ الْفَجْرُ ‏","","",""],[3631,3631,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ عَبْدِ اللَّهِ الْبَجَلِيُّ ‏ ‏عَنْ ‏ ‏كَرِيمِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏سَلْمَى بِنْتِ جَابِرٍ ‏ ‏أَنَّ زَوْجَهَا اسْتُشْهِدَ فَأَتَتْ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏فَقَالَتْ إِنِّي امْرَأَةٌ قَدْ اسْتُشْهِدَ زَوْجِي وَقَدْ خَطَبَنِي الرِّجَالُ فَأَبَيْتُ أَنْ أَتَزَوَّجَ حَتَّى أَلْقَاهُ ‏ ‏فَتَرْجُو لِي إِنْ اجْتَمَعْتُ أَنَا وَهُوَ أَنْ أَكُونَ مِنْ أَزْوَاجِهِ قَالَ نَعَمْ فَقَالَ لَهُ رَجُلٌ مَا رَأَيْنَاكَ نَقَلْتَ هَذَا مُذْ قَاعَدْنَاكَ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَسْرَعَ أُمَّتِي بِي لُحُوقًا فِي الْجَنَّةِ امْرَأَةٌ مِنْ ‏ ‏أَحْمَسَ ‏","","",""],[3632,3632,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَاضِرٌ أَبُو الْمُوَرِّعِ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏عَوْسَجَةَ بْنِ الرَّمَّاحِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْهُذَيْلِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ أَحْسَنْتَ خَلْقِي فَأَحْسِنْ خُلُقِي ‏","","",""],[3633,3633,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏أَبَا جَهْلٍ ‏ ‏وَقَدْ جُرِحَ وَقُطِعَتْ رِجْلُهُ قَالَ فَجَعَلْتُ أَضْرِبُهُ بِسَيْفِي فَلَا يَعْمَلُ فِيهِ شَيْئًا ‏ ‏قِيلَ ‏ ‏لِشَرِيكٍ ‏ ‏فِي الْحَدِيثِ وَكَانَ ‏ ‏يَذُبُّ ‏ ‏بِسَيْفِهِ قَالَ نَعَمْ ‏ ‏قَالَ فَلَمْ أَزَلْ حَتَّى أَخَذْتُ سَيْفَهُ فَضَرَبْتُهُ بِهِ حَتَّى قَتَلْتُهُ قَالَ ثُمَّ قَالَ أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ قَدْ قُتِلَ ‏ ‏أَبُو جَهْلٍ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏شَرِيكٌ ‏ ‏قَدْ قَتَلْتُ ‏ ‏أَبَا جَهْلٍ ‏ ‏قَالَ أَنْتَ رَأَيْتَهُ قُلْتُ نَعَمْ قَالَ ‏ ‏آللَّهِ مَرَّتَيْنِ قُلْتُ نَعَمْ قَالَ فَاذْهَبْ حَتَّى أَنْظُرَ إِلَيْهِ فَذَهَبَ فَأَتَاهُ وَقَدْ غَيَّرَتْ الشَّمْسُ مِنْهُ شَيْئًا فَأَمَرَ بِهِ وَبِأَصْحَابِهِ فَسُحِبُوا حَتَّى أُلْقُوا فِي ‏ ‏الْقَلِيبِ ‏ ‏قَالَ وَأُتْبِعَ أَهْلُ ‏ ‏الْقَلِيبِ ‏ ‏لَعْنَةً وَقَالَ كَانَ ‏ ‏هَذَا فِرْعَوْنَ هَذِهِ الْأُمَّةِ ‏ ‏حَدَّثَنَا ‏ ‏أَسْودُ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏هَذَا فِرْعَوْنُ أُمَّتِي ‏","","",""],[3634,3634,"","","‏ ‏حَدَّثَنَا ‏ ‏طَلْقُ بْنُ غَنَّامِ بْنِ طَلْقٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَيْخٌ مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏إِمَّا ‏ ‏قَالَ ‏ ‏شَقِيقٌ ‏ ‏وَإِمَّا ‏ ‏قَالَ ‏ ‏زِرٌّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو لِهَذَا الْحَيِّ مِنْ ‏ ‏النَّخَعِ ‏ ‏أَوْ قَالَ ‏ ‏يُثْنِي ‏ ‏عَلَيْهِمْ ‏ ‏حَتَّى تَمَنَّيْتُ أَنِّي رَجُلٌ مِنْهُمْ ‏","","",""],[3635,3635,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ اللَّحْمَ ثُمَّ يَقُومُ إِلَى الصَّلَاةِ فَمَا يَمَسُّ قَطْرَةً مِنْ مَاءٍ ‏","","",""],[3636,3636,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَتَعَوَّذُ مِنْ الشَّيْطَانِ مِنْ ‏ ‏هَمْزِهِ ‏ ‏وَنَفْثِهِ ‏ ‏وَنَفْخِهِ ‏ ‏قَالَ ‏ ‏وَهَمْزُهُ ‏ ‏الْمُوتَةُ وَنَفْثُهُ الشِّعْرُ ‏ ‏وَنَفْخُهُ ‏ ‏الْكِبْرِيَاءُ ‏","","",""],[3637,3637,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏حَبَسَ ‏ ‏الْمُشْرِكُونَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةِ الْعَصْرِ حَتَّى اصْفَرَّتْ أَوْ احْمَرَّتْ الشَّمْسُ فَقَالَ ‏ ‏شَغَلُونَا عَنْ صَلَاةِ الْوُسْطَى مَلَأَ اللَّهُ أَجْوَافَهُمْ ‏ ‏أَوْ حَشَا اللَّهُ أَجْوَافَهُمْ ‏ ‏وَقُبُورَهُمْ نَارًا ‏","","",""],[3638,3638,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الشَّيْطَانِ مِنْ ‏ ‏هَمْزِهِ ‏ ‏وَنَفْثِهِ ‏ ‏وَنَفْخِهِ ‏ ‏فَهَمْزُهُ ‏ ‏الْمُوتَةُ ‏ ‏وَنَفْثُهُ ‏ ‏الشِّعْرُ ‏ ‏وَنَفْخُهُ ‏ ‏الْكِبْرُ ‏","","",""],[3639,3639,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ قَوْمٌ فِي آخِرِ الزَّمَانِ ‏ ‏سُفَهَاءُ ‏ ‏الْأَحْلَامِ ‏ ‏أَحْدَاثٌ ‏ ‏أَوْ قَالَ حُدَثَاءُ الْأَسْنَانِ ‏ ‏يَقُولُونَ مِنْ خَيْرِ قَوْلِ النَّاسِ يَقْرَءُونَ الْقُرْآنَ بِأَلْسِنَتِهِمْ لَا يَعْدُو ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الْإِسْلَامِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏فَمَنْ أَدْرَكَهُمْ فَلْيَقْتُلْهُمْ فَإِنَّ فِي قَتْلِهِمْ أَجْرًا عَظِيمًا عِنْدَ اللَّهِ لِمَنْ قَتَلَهُمْ ‏","","",""],[3640,3640,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ أَظْهَرَ إِسْلَامَهُ سَبْعَةٌ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعَمَّارٌ ‏ ‏وَأُمُّهُ ‏ ‏سُمَيَّةُ ‏ ‏وَصُهَيْبٌ ‏ ‏وَبِلَالٌ ‏ ‏وَالْمِقْدَادُ ‏ ‏فَأَمَّا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَنَعَهُ اللَّهُ بِعَمِّهِ ‏ ‏أَبِي طَالِبٍ ‏ ‏وَأَمَّا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَمَنَعَهُ اللَّهُ بِقَوْمِهِ وَأَمَّا سَائِرُهُمْ فَأَخَذَهُمْ الْمُشْرِكُونَ فَأَلْبَسُوهُمْ أَدْرَاعَ الْحَدِيدِ وَصَهَرُوهُمْ فِي الشَّمْسِ فَمَا مِنْهُمْ إِنْسَانٌ إِلَّا وَقَدْ وَاتَاهُمْ عَلَى مَا أَرَادُوا إِلَّا ‏ ‏بِلَالٌ ‏ ‏فَإِنَّهُ هَانَتْ عَلَيْهِ نَفْسُهُ فِي اللَّهِ وَهَانَ عَلَى قَوْمِهِ فَأَعْطَوْهُ الْوِلْدَانَ وَأَخَذُوا يَطُوفُونَ بِهِ ‏ ‏شِعَابَ ‏ ‏مَكَّةَ ‏ ‏وَهُوَ يَقُولُ أَحَدٌ أَحَدٌ ‏","","",""],[3641,3641,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذْنُكَ عَلَيَّ أَنْ تَرْفَعَ الْحِجَابَ وَأَنْ تَسْتَمِعَ ‏ ‏سِوَادِي ‏ ‏حَتَّى ‏ ‏أَنْهَاكَ ‏","","",""],[3642,3642,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏سَمِعْتُهُمْ ‏ ‏يَذْكُرُونَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْنُكَ عَلَيَّ أَنْ تَكْشِفَ السِّتْرَ ‏","","",""],[3643,3643,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلًا فَانْطَلَقَ إِنْسَانٌ إِلَى ‏ ‏غَيْضَةٍ ‏ ‏فَأَخْرَجَ مِنْهَا بَيْضَ ‏ ‏حُمَرَةٍ فَجَاءَتْ ‏ ‏اَلْحُمَرَةُ ‏ ‏تَرِفُّ عَلَى رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرُءُوسِ أَصْحَابِهِ فَقَالَ ‏ ‏أَيُّكُمْ فَجَعَ هَذِهِ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ أَنَا ‏ ‏أَصَبْتُ ‏ ‏لَهَا بَيْضًا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْدُدْهُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلًا فَذَكَرَ مِثْلَهُ وَقَالَ رُدَّهُ رَحْمَةً لَهَا ‏","","",""],[3644,3644,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏ابْنِ مُعَيْزٍ السَّعْدِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْتُ أَسْقِي فَرَسًا لِي فِي ‏ ‏السَّحَرِ ‏ ‏فَمَرَرْتُ بِمَسْجِدِ ‏ ‏بَنِي حَنِيفَةَ ‏ ‏وَهُمْ يَقُولُونَ إِنَّ ‏ ‏مُسَيْلِمَةَ ‏ ‏رَسُولُ اللَّهِ فَأَتَيْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَأَخْبَرْتُهُ فَبَعَثَ الشُّرْطَةَ فَجَاءُوا بِهِمْ ‏ ‏فَاسْتَتَابَهُمْ ‏ ‏فَتَابُوا فَخَلَّى سَبِيلَهُمْ وَضَرَبَ عُنُقَ ‏ ‏عَبْدِ اللَّهِ بْنِ النَّوَّاحَةِ ‏ ‏فَقَالُوا آخَذْتَ قَوْمًا فِي أَمْرٍ وَاحِدٍ فَقَتَلْتَ بَعْضَهُمْ وَتَرَكْتَ بَعْضَهُمْ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدِمَ عَلَيْهِ هَذَا ‏ ‏وَابْنُ أُثَالِ بْنِ حَجَرٍ ‏ ‏فَقَالَ ‏ ‏أَتَشْهَدَانِ أَنِّي رَسُولُ اللَّهِ فَقَالَا نَشْهَدُ أَنَّ ‏ ‏مُسَيْلِمَةَ ‏ ‏رَسُولُ اللَّهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آمَنْتُ بِاللَّهِ وَرُسُلِهِ لَوْ كُنْتُ قَاتِلًا وَفْدًا لَقَتَلْتُكُمَا فَلِذَلِكَ قَتَلْتُهُ ‏","","",""],[3645,3645,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجِيبُوا الدَّاعِيَ وَلَا تَرُدُّوا الْهَدِيَّةَ وَلَا تَضْرِبُوا الْمُسْلِمِينَ ‏","","",""],[3646,3646,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْمُؤْمِنُ بِطَعَّانٍ وَلَا بِلَعَّانٍ وَلَا ‏ ‏الْفَاحِشِ ‏ ‏الْبَذِيءِ ‏ ‏وَقَالَ ‏ ‏ابْنُ سَابِقٍ ‏ ‏مَرَّةً ‏ ‏بِالطَّعَّانِ ‏ ‏وَلَا ‏ ‏بِاللَّعَّانِ ‏","","",""],[3647,3647,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ دِينَارٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَمْرَو بْنَ الْحَارِثِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏مَا صُمْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعَةً وَعِشْرِينَ أَكْثَرُ مِمَّا صُمْتُ مَعَهُ ثَلَاثِينَ ‏","","",""],[3648,3648,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَأَبِي مُوسَى ‏ ‏وَهُمَا يَتَحَدَّثَانِ فَقَالَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ يَدَيْ السَّاعَةِ أَيَّامٌ يُرْفَعُ فِيهَا الْعِلْمُ وَيَنْزِلُ فِيهِنَّ الْجَهْلُ وَيَظْهَرُ فِيهِنَّ ‏ ‏الْهَرْجُ ‏ ‏وَالْهَرْجُ ‏ ‏الْقَتْلُ ‏","","",""],[3649,3649,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا قُبِضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏مِنَّا أَمِيرٌ وَمِنْكُمْ أَمِيرٌ فَأَتَاهُمْ ‏ ‏عُمَرُ ‏ ‏فَقَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَسْتُمْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يَؤُمَّ النَّاسَ قَالُوا بَلَى قَالَ فَأَيُّكُمْ تَطِيبُ نَفْسُهُ أَنْ يَتَقَدَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏قَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏نَعُوذُ بِاللَّهِ أَنْ نَتَقَدَّمَ ‏ ‏أَبَا بَكْرٍ ‏","","",""],[3650,3650,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَحِقَ بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدٌ أَسْوَدُ فَمَاتَ فَأُوذِنَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏انْظُرُوا هَلْ تَرَكَ شَيْئًا فَقَالُوا تَرَكَ دِينَارَيْنِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيَّتَانِ ‏","","",""],[3651,3651,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ شِرَارِ النَّاسِ مَنْ تُدْرِكُهُ السَّاعَةُ وَهُمْ أَحْيَاءٌ وَمَنْ يَتَّخِذُ الْقُبُورَ مَسَاجِدَ ‏","","",""],[3652,3652,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏هَمْدَانَ ‏ ‏مِنْ أَصْحَابِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَمَا سَمَّاهُ لَنَا ‏ ‏قَالَ ‏ ‏لَمَّا أَرَادَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَنْ يَأْتِيَ ‏ ‏الْمَدِينَةَ ‏ ‏جَمَعَ أَصْحَابَهُ فَقَالَ وَاللَّهِ إِنِّي لَأَرْجُو أَنْ يَكُونَ قَدْ أَصْبَحَ الْيَوْمَ فِيكُمْ مِنْ أَفْضَلِ مَا أَصْبَحَ فِي أَجْنَادِ الْمُسْلِمِينَ مِنْ الدِّينِ وَالْفِقْهِ وَالْعِلْمِ بِالْقُرْآنِ ‏ ‏إِنَّ هَذَا الْقُرْآنَ أُنْزِلَ عَلَى حُرُوفٍ وَاللَّهِ إِنْ كَانَ الرَّجُلَانِ لَيَخْتَصِمَانِ أَشَدَّ مَا اخْتَصَمَا فِي شَيْءٍ قَطُّ فَإِذَا قَالَ الْقَارِئُ هَذَا أَقْرَأَنِي قَالَ أَحْسَنْتَ وَإِذَا قَالَ الْآخَرُ قَالَ كِلَاكُمَا مُحْسِنٌ فَأَقْرَأَنَا إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ وَالْبِرَّ يَهْدِي إِلَى الْجَنَّةِ وَالْكَذِبَ يَهْدِي إِلَى الْفُجُورِ وَالْفُجُورَ يَهْدِي إِلَى النَّارِ وَاعْتَبِرُوا ذَاكَ بِقَوْلِ أَحَدِكُمْ لِصَاحِبِهِ كَذَبَ وَفَجَرَ وَبِقَوْلِهِ إِذَا صَدَّقَهُ صَدَقْتَ ‏ ‏وَبَرَرْتَ ‏ ‏إِنَّ هَذَا الْقُرْآنَ لَا يَخْتَلِفُ وَلَا ‏ ‏يُسْتَشَنُّ ‏ ‏وَلَا يَتْفَهُ لِكَثْرَةِ الرَّدِّ فَمَنْ قَرَأَهُ عَلَى حَرْفٍ فَلَا يَدَعْهُ رَغْبَةً عَنْهُ وَمَنْ قَرَأَهُ عَلَى شَيْءٍ مِنْ تِلْكَ الْحُرُوفِ الَّتِي عَلَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا يَدَعْهُ رَغْبَةً عَنْهُ فَإِنَّهُ مَنْ يَجْحَدْ بِآيَةٍ مِنْهُ يَجْحَدْ بِهِ كُلِّهِ فَإِنَّمَا هُوَ كَقَوْلِ أَحَدِكُمْ لِصَاحِبِهِ ‏ ‏اعْجَلْ ‏ ‏وَحَيَّ ‏ ‏هَلًا وَاللَّهِ لَوْ أَعْلَمُ رَجُلًا أَعْلَمَ بِمَا أَنْزَلَ اللَّهُ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنِّي لَطَلَبْتُهُ حَتَّى أَزْدَادَ عِلْمَهُ إِلَى عِلْمِي إِنَّهُ سَيَكُونُ قَوْمٌ ‏ ‏يُمِيتُونَ ‏ ‏الصَّلَاةَ فَصَلُّوا الصَّلَاةَ لِوَقْتِهَا وَاجْعَلُوا صَلَاتَكُمْ مَعَهُمْ تَطَوُّعًا وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُعَارَضُ بِالْقُرْآنِ فِي كُلِّ رَمَضَانَ وَإِنِّي عَرَضْتُ فِي الْعَامِ الَّذِي قُبِضَ فِيهِ مَرَّتَيْنِ فَأَنْبَأَنِي أَنِّي مُحْسِنٌ وَقَدْ قَرَأْتُ مِنْ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعِينَ سُورَةً ‏","","",""],[3653,3653,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏خُمَيْرِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ مِنْ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعِينَ سُورَةً وَإِنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏لَهُ ‏ ‏ذُؤَابَةٌ ‏ ‏فِي الْكُتَّابِ ‏","","",""],[3654,3654,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏و حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ جَهَنَّمَ ‏ ‏قَالَ ‏ ‏أَحَدُهُمْ مِنْ النَّارِ ‏","","",""],[3655,3655,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَيَّاشٍ الْعَامِرِيِّ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ هِلَالٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ أَنْ يُسَلِّمَ الرَّجُلُ عَلَى الرَّجُلِ لَا يُسَلِّمُ عَلَيْهِ إِلَّا لِلْمَعْرِفَةِ ‏","","",""],[3656,3656,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَحُسَيْنٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏وَالْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى يَبْدُوَ بَيَاضُ خَدِّهِ الْأَيْمَنِ وَعَنْ يَسَارِهِ بِمِثْلِ ذَلِكَ ‏","","",""],[3657,3657,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ وَلَأُنَازَعَنَّ رِجَالًا مِنْ أَصْحَابِي وَلَأُغْلَبَنَّ عَلَيْهِمْ ثُمَّ لَيُقَالَنَّ لِي إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ ‏","","",""],[3658,3658,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَنْبَأَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏صِلَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ ‏ ‏مُسَيْلِمَةَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ أَتَشْهَدُ أَنِّي رَسُولُ اللَّهِ فَقَالَ لَهُ شَيْئًا فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنِّي لَا أَقْتُلُ الرُّسُلَ ‏ ‏أَوْ لَوْ قَتَلْتُ أَحَدًا مِنْ الرُّسُلِ ‏ ‏لَقَتَلْتُكَ ‏","","",""],[3659,3659,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ قَدْ ‏ ‏نُعِتَ ‏ ‏لَهُ الْكَيُّ فَقَالَ اكْوُوهُ أَوْ ارْضِفُوهُ ‏","","",""],[3660,3660,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَقْرَأُ ‏ { ‏فَهَلْ مِنْ ‏ ‏مُدَّكِرٍ ‏ }","","",""],[3661,3661,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ يَحْيَى ‏ ‏مِنْ أَهْلِ ‏ ‏مَرْوٍ ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ مِنْ امْرَأَةٍ كُلَّ شَيْءٍ إِلَّا أَنِّي لَمْ أُجَامِعْهَا قَالَ فَأَنْزَلَ اللَّهُ ‏ { ‏أَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ ‏ ‏وَزُلَفًا ‏ ‏مِنْ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ‏}","","",""],[3662,3662,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ ‏ ‏لَوْلَا أَنَّكَ رَسُولٌ لَقَتَلْتُكَ ‏","","",""],[3663,3663,"","","‏ ‏حَدَّثَنَا ‏ ‏أُمَيَّةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ قَدْ قَتَلَ ‏ ‏أَبَا جَهْلٍ ‏ ‏فَقَالَ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي نَصَرَ عَبْدَهُ وَأَعَزَّ دِينَهُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏يَعْنِي ‏ ‏أُمَيَّةَ ‏ ‏صَدَقَ عَبْدَهُ وَأَعَزَّ دِينَهُ ‏","","",""],[3664,3664,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي الْيَعْفُورِ ‏ ‏عَنْ ‏ ‏أَبِي الصَّلْتِ ‏ ‏عَنْ ‏ ‏أَبِي عَقْرَبٍ ‏ ‏قَالَ ‏ ‏غَدَوْتُ ‏ ‏إِلَى ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏ذَاتَ ‏ ‏غَدَاةٍ ‏ ‏فِي رَمَضَانَ فَوَجَدْتُهُ فَوْقَ بَيْتِهِ جَالِسًا فَسَمِعْنَا صَوْتَهُ وَهُوَ يَقُولُ صَدَقَ اللَّهُ وَبَلَّغَ رَسُولُهُ فَقُلْنَا سَمِعْنَاكَ تَقُولُ صَدَقَ اللَّهُ وَبَلَّغَ رَسُولُهُ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لَيْلَةَ الْقَدْرِ فِي النِّصْفِ مِنْ السَّبْعِ الْأَوَاخِرِ مِنْ رَمَضَانَ تَطْلُعُ الشَّمْسُ ‏ ‏غَدَاتَئِذٍ ‏ ‏صَافِيَةً لَيْسَ لَهَا شُعَاعٌ فَنَظَرْتُ إِلَيْهَا فَوَجَدْتُهَا كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يَعْفُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الصَّلْتِ ‏ ‏عَنْ ‏ ‏أَبِي عَقْرَبٍ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏غَدَوْتُ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[3665,3665,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏جُلُوسًا فِي الْمَسْجِدِ يُقْرِئُنَا فَأَتَاهُ رَجُلٌ فَقَالَ يَا ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏هَلْ حَدَّثَكُمْ نَبِيُّكُمْ كَمْ يَكُونُ مِنْ بَعْدِهِ خَلِيفَةً قَالَ ‏ ‏نَعَمْ كَعِدَّةِ نُقَبَاءِ ‏ ‏بَنِي إِسْرَائِيلَ ‏","","",""],[3666,3666,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ ‏ ‏غُرَّةِ ‏ ‏كُلِّ هِلَالٍ وَقَلَّمَا كَانَ يُفْطِرُ يَوْمَ الْجُمُعَةِ ‏","","",""],[3667,3667,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ ‏ ‏أَسْفَارِهِ سَمِعْنَا مُنَادِيًا يُنَادِي اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْفِطْرَةِ فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ النَّارِ قَالَ فَابْتَدَرْنَاهُ فَإِذَا هُوَ صَاحِبُ مَاشِيَةٍ أَدْرَكَتْهُ الصَّلَاةُ فَنَادَى بِهَا ‏","","",""],[3668,3668,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ حُبَابٍ ‏ ‏حَدَّثَنِي ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَقِيقَ بْنَ سَلَمَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ ‏ ‏جِبْرِيلَ ‏ ‏عَلَى سِدْرَةِ الْمُنْتَهَى وَلَهُ سِتُّ مِائَةِ جَنَاحٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَاصِمًا ‏ ‏عَنْ الْأَجْنِحَةِ فَأَبَى أَنْ يُخْبِرَنِي قَالَ فَأَخْبَرَنِي بَعْضُ أَصْحَابِهِ أَنَّ الْجَنَاحَ مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ ‏","","",""],[3669,3669,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنِي ‏ ‏حُصَيْنٌ ‏ ‏حَدَّثَنِي ‏ ‏شَقِيقٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏فِي خُضْرٍ مُعَلَّقٌ بِهِ الدُّرُّ ‏","","",""],[3670,3670,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ أَبِي الْكَهْتَلَةِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏أَظُنُّهُ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ ‏ ‏مُحَمَّداً ‏ ‏لَمْ يَرَ ‏ ‏جِبْرِيلَ ‏ ‏فِي صُورَتِهِ إِلَّا مَرَّتَيْنِ أَمَّا مَرَّةٌ فَإِنَّهُ سَأَلَهُ أَنْ يُرِيَهُ نَفْسَهُ فِي صُورَتِهِ فَأَرَاهُ صُورَتَهُ فَسَدَّ ‏ ‏الْأُفُقَ ‏ ‏وَأَمَّا الْأُخْرَى فَإِنَّهُ صَعِدَ مَعَهُ حِينَ صَعِدَ بِهِ وَقَوْلُهُ ‏ { ‏وَهُوَ بِالْأُفُقِ الْأَعْلَى ثُمَّ دَنَا ‏ ‏فَتَدَلَّى ‏ ‏فَكَانَ ‏ ‏قَابَ ‏ ‏قَوْسَيْنِ أَوْ أَدْنَى فَأَوْحَى إِلَى عَبْدِهِ مَا أَوْحَى ‏} ‏قَالَ فَلَمَّا أَحَسَّ ‏ ‏جِبْرِيلُ ‏ ‏رَبَّهُ عَادَ فِي صُورَتِهِ وَسَجَدَ فَقَوْلُهُ ‏ { ‏وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى عِنْدَ سِدْرَةِ الْمُنْتَهَى عِنْدَهَا جَنَّةُ الْمَأْوَى إِذْ ‏ ‏يَغْشَى ‏ ‏السِّدْرَةَ مَا ‏ ‏يَغْشَى ‏ ‏مَا زَاغَ الْبَصَرُ وَمَا طَغَى لَقَدْ رَأَى مِنْ آيَاتِ رَبِّهِ الْكُبْرَى ‏} ‏قَالَ خَلْقَ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[3671,3671,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ جَعَلَ لِلَّهِ ‏ ‏نِدًّا ‏ ‏جَعَلَهُ اللَّهُ فِي النَّارِ ‏ ‏قَالَ ‏ ‏وَأُخْرَى أَقُولُهَا لَمْ أَسْمَعْهَا مِنْهُ وَمَنْ مَاتَ لَا يَجْعَلُ لِلَّهِ ‏ ‏نِدًّا ‏ ‏أَدْخَلَهُ اللَّهُ عَزَّ وَجَلَّ الْجَنَّةَ وَإِنَّ هَذِهِ الصَّلَوَاتِ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ مَا اجْتُنِبَ الْمَقْتَلُ ‏","","",""],[3672,3672,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنِّي ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ وَإِنِّي سَأُنَازَعُ رِجَالًا فَأُغْلَبُ عَلَيْهِمْ فَأَقُولُ يَا رَبِّ أَصْحَابِي فَيَقُولُ إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[3673,3673,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ السَّلَامِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ فِي السَّفَرِ وَيُفْطِرُ وَيُصَلِّي الرَّكْعَتَيْنِ لَا يَدَعُهُمَا ‏ ‏يَقُولُ ‏ ‏لَا يَزِيدُ عَلَيْهِمَا ‏ ‏يَعْنِي الْفَرِيضَةَ ‏","","",""],[3674,3674,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَشَدُّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ رَجُلٌ قَتَلَهُ نَبِيٌّ أَوْ قَتَلَ نَبِيًّا وَإِمَامُ ضَلَالَةٍ وَمُمَثِّلٌ مِنْ الْمُمَثِّلِينَ ‏","","",""],[3675,3675,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بَشِيرُ بْنُ سَلْمَانَ ‏ ‏كَانَ يَنْزِلُ فِي مَسْجِدِ ‏ ‏الْمَطْمُورَةِ ‏ ‏عَنْ ‏ ‏سَيَّارٍ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَصَابَتْهُ ‏ ‏فَاقَةٌ ‏ ‏فَأَنْزَلَهَا بِالنَّاسِ لَمْ تُسَدَّ ‏ ‏فَاقَتُهُ ‏ ‏وَمَنْ أَنْزَلَهَا بِاللَّهِ عَزَّ وَجَلَّ أَوْشَكَ اللَّهُ لَهُ بِالْغِنَى إِمَّا أَجَلٌ عَاجِلٌ أَوْ غِنًى عَاجِلٌ ‏","","",""],[3676,3676,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بَشِيرُ بْنُ سَلْمَانَ ‏ ‏عَنْ ‏ ‏سَيَّارٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏جُلُوسًا فَجَاءَ رَجُلٌ فَقَالَ قَدْ أُقِيمَتْ الصَّلَاةُ فَقَامَ وَقُمْنَا مَعَهُ فَلَمَّا دَخَلْنَا الْمَسْجِدَ رَأَيْنَا النَّاسَ رُكُوعًا فِي مُقَدَّمِ الْمَسْجِدِ فَكَبَّرَ وَرَكَعَ وَرَكَعْنَا ثُمَّ مَشَيْنَا وَصَنَعْنَا مِثْلَ الَّذِي صَنَعَ فَمَرَّ رَجُلٌ يُسْرِعُ فَقَالَ عَلَيْكَ السَّلَامُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏فَقَالَ صَدَقَ اللَّهُ وَرَسُولُهُ فَلَمَّا صَلَّيْنَا وَرَجَعْنَا دَخَلَ إِلَى أَهْلِهِ جَلَسْنَا فَقَالَ بَعْضُنَا لِبَعْضٍ أَمَا سَمِعْتُمْ رَدَّهُ عَلَى الرَّجُلِ صَدَقَ اللَّهُ وَبَلَّغَتْ رُسُلُهُ أَيُّكُمْ يَسْأَلُهُ فَقَالَ ‏ ‏طَارِقٌ ‏ ‏أَنَا أَسْأَلُهُ فَسَأَلَهُ حِينَ خَرَجَ فَذَكَرَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ بَيْنَ يَدَيْ السَّاعَةِ تَسْلِيمَ الْخَاصَّةِ وَفُشُوَّ التِّجَارَةِ ‏ ‏حَتَّى تُعِينَ الْمَرْأَةُ زَوْجَهَا عَلَى التِّجَارَةِ وَقَطْعَ الْأَرْحَامِ وَشَهَادَةَ الزُّورِ وَكِتْمَانَ شَهَادَةِ الْحَقِّ وَظُهُورَ الْقَلَمِ ‏","","",""],[3677,3677,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ بْنِ أَبِي ضِرَارٍ الْخُزَاعِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏مَا صُمْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعًا وَعِشْرِينَ أَكْثَرُ مِمَّا صُمْتُ مَعَهُ ثَلَاثِينَ ‏","","",""],[3678,3678,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ عَامَّةً مَا يَنْصَرِفُ مِنْ الصَّلَاةِ عَلَى يَسَارِهِ إِلَى ‏ ‏الْحُجُرَاتِ ‏","","",""],[3679,3679,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَأَنْ أَحْلِفَ تِسْعًا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُتِلَ قَتْلًا أَحَبُّ إِلَيَّ مِنْ أَنْ أَحْلِفَ وَاحِدَةً أَنَّهُ لَمْ يُقْتَلْ وَذَلِكَ بِأَنَّ اللَّهَ جَعَلَهُ نَبِيًّا وَاتَّخَذَهُ شَهِيدًا ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَقَالَ ‏ ‏كَانُوا يَرَوْنَ أَنَّ ‏ ‏الْيَهُودَ ‏ ‏سَمُّوهُ ‏ ‏وَأَبَا بَكْرٍ ‏","","",""],[3680,3680,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَرْمِي الْجَمْرَةَ مِنْ ‏ ‏الْمَسِيلِ ‏ ‏فَقُلْتُ أَمِنْ هَاهُنَا ‏ ‏تَرْمِيهَا فَقَالَ مِنْ هَاهُنَا وَالَّذِي لَا إِلَهَ غَيْرُهُ رَمَاهَا الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[3681,3681,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنِّي لَمُسْتَتِرٌ بِأَسْتَارِ ‏ ‏الْكَعْبَةِ ‏ ‏إِذْ جَاءَ ثَلَاثَةُ ‏ ‏نَفَرٍ ‏ ‏ثَقَفِيٌّ ‏ ‏وَخَتْنَاهُ ‏ ‏قُرَشِيَّانِ ‏ ‏كَثِيرٌ شَحْمُ بُطُونِهِمْ قَلِيلٌ فِقْهُ قُلُوبِهِمْ فَتَحَدَّثُوا بَيْنَهُمْ بِحَدِيثٍ قَالَ فَقَالَ أَحَدُهُمْ تُرَى أَنَّ اللَّهَ عَزَّ وَجَلَّ يَسْمَعُ مَا قُلْنَا قَالَ الْآخَرُ أُرَاهُ يَسْمَعُ إِذَا رَفَعْنَا وَلَا يَسْمَعُ إِذَا خَفَضْنَا قَالَ الْآخَرَانِ كَانَ يَسْمَعُ شَيْئًا مِنْهُ إِنَّهُ لَيَسْمَعُهُ كُلَّهُ قَالَ فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَمَا كُنْتُمْ تَسْتَتِرُونَ أَنْ يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ ‏ ‏حَتَّى ‏ ‏الْخَاسِرِينَ ‏}","","",""],[3682,3682,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ ذَرٍّ ‏ ‏عَنْ ‏ ‏الْعَيْزَارِ بْنِ جَرْوَلٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْهُمْ يُكْنَى ‏ ‏أَبَا عُمَيْرٍ ‏ ‏أَنَّهُ كَانَ صَدِيقًا ‏ ‏لِعَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَإِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏زَارَهُ فِي أَهْلِهِ فَلَمْ يَجِدْهُ قَالَ فَاسْتَأْذَنَ عَلَى أَهْلِهِ وَسَلَّمَ فَاسْتَسْقَى قَالَ فَبَعَثَتْ الْجَارِيَةَ تَجِيئُهُ بِشَرَابٍ مِنْ الْجِيرَانِ فَأَبْطَأَتْ فَلَعَنَتْهَا فَخَرَجَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَجَاءَ ‏ ‏أَبُو عُمَيْرٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏لَيْسَ مِثْلُكَ يُغَارُ عَلَيْهِ هَلَّا سَلَّمْتَ عَلَى أَهْلِ أَخِيكَ وَجَلَسْتَ وَأَصَبْتَ مِنْ الشَّرَابِ قَالَ قَدْ فَعَلْتُ فَأَرْسَلَتْ الْخَادِمَ فَأَبْطَأَتْ إِمَّا لَمْ يَكُنْ عِنْدَهُمْ وَإِمَّا رَغِبُوا فِيمَا عِنْدَهُمْ فَأَبْطَأَتْ الْخَادِمُ فَلَعَنَتْهَا وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّعْنَةَ إِلَى مَنْ وُجِّهَتْ إِلَيْهِ فَإِنْ أَصَابَتْ عَلَيْهِ سَبِيلًا أَوْ وَجَدَتْ فِيهِ مَسْلَكًا وَإِلَّا قَالَتْ يَا رَبِّ وُجِّهْتُ إِلَى فُلَانٍ فَلَمْ أَجِدْ عَلَيْهِ سَبِيلًا وَلَمْ أَجِدْ فِيهِ مَسْلَكًا فَيُقَالُ لَهَا ارْجِعِي مِنْ حَيْثُ جِئْتِ فَخَشِيتُ أَنْ تَكُونَ الْخَادِمُ مَعْذُورَةً فَتَرْجِعَ اللَّعْنَةُ فَأَكُونَ سَبَبَهَا ‏","","",""],[3683,3683,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُلِّمَ فَوَاتِحَ الْخَيْرِ وَجَوَامِعَهُ ‏ ‏أَوْ جَوَامِعَ الْخَيْرِ وَفَوَاتِحَهُ ‏ ‏وَإِنَّا كُنَّا لَا نَدْرِي مَا نَقُولُ فِي صَلَاتِنَا حَتَّى عُلِّمْنَا فَقَالَ قُولُوا ‏ ‏التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏","","",""],[3684,3684,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ مُتَّخِذًا أَحَدًا خَلِيلًا لَاتَّخَذْتُ ‏ ‏ابْنَ أَبِي قُحَافَةَ ‏ ‏خَلِيلًا ‏","","",""],[3685,3685,"","","‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ ‏","","",""],[3686,3686,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَبْرَأُ إِلَى كُلِّ ‏ ‏خَلِيلٍ ‏ ‏مِنْ ‏ ‏خُلَّتِهِ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏ابْنَ أَبِي قُحَافَةَ ‏ ‏خَلِيلًا ‏ ‏وَإِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3687,3687,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ اللَّهِ الْأَعْوَرِ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏آكِلُ الرِّبَا ‏ ‏وَمُوكِلُهُ وَكَاتِبُهُ وَشَاهِدَاهُ إِذَا عَلِمُوا بِهِ ‏ ‏وَالْوَاشِمَةُ ‏ ‏وَالْمُسْتَوْشِمَةُ ‏ ‏لِلْحُسْنِ وَلَاوِي ‏ ‏الصَّدَقَةِ ‏ ‏وَالْمُرْتَدُّ أَعْرَابِيًّا بَعْدَ هِجْرَتِهِ مَلْعُونُونَ عَلَى لِسَانِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏فَذَكَرْتُهُ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏عَلْقَمَةُ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏آكِلُ الرِّبَا ‏ ‏وَمُوكِلُهُ سَوَاءٌ ‏","","",""],[3688,3688,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَفَّ صَفَّا خَلْفَهُ وَصَفٌّ ‏ ‏مُوَازِي ‏ ‏الْعَدُوِّ قَالَ وَهُمْ فِي صَلَاةٍ كُلُّهُمْ قَالَ وَكَبَّرَ وَكَبَّرُوا جَمِيعًا فَصَلَّى بِالصَّفِّ الَّذِي يَلِيهِ رَكْعَةً وَصَفٌّ ‏ ‏مُوَازِي ‏ ‏الْعَدُوِّ قَالَ ثُمَّ ذَهَبَ هَؤُلَاءِ وَجَاءَ هَؤُلَاءِ فَصَلَّى بِهِمْ رَكْعَةً ثُمَّ قَامَ هَؤُلَاءِ الَّذِينَ صَلَّى بِهِمْ الرَّكْعَةَ الثَّانِيَةَ ‏ ‏فَقَضَوْا ‏ ‏مَكَانَهُمْ ثُمَّ ذَهَبَ هَؤُلَاءِ إِلَى ‏ ‏مَصَافِّ ‏ ‏هَؤُلَاءِ وَجَاءَ أُولَئِكَ ‏ ‏فَقَضَوْا ‏ ‏رَكْعَةً ‏","","",""],[3689,3689,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ ‏ ‏أَوْ الْعَصْرَ ‏ ‏خَمْسًا ثُمَّ سَجَدَ سَجْدَتَيْ السَّهْوِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَاتَانِ السَّجْدَتَانِ لِمَنْ ظَنَّ مِنْكُمْ أَنَّهُ زَادَ أَوْ نَقَصَ ‏","","",""],[3690,3690,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏كُنَّا نُسَلِّمُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ حَتَّى رَجَعْنَا مِنْ عِنْدِ ‏ ‏النَّجَاشِيِّ ‏ ‏فَسَلَّمْنَا عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْنَا وَقَالَ ‏ ‏إِنَّ فِي الصَّلَاةِ شُغْلًا ‏","","",""],[3691,3691,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏أَبِي الْجَهْمِ ‏ ‏عَنْ ‏ ‏أَبِي الرَّضْرَاضِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أُسَلِّمُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ فَيَرُدُّ عَلَيَّ فَلَمَّا كَانَ ذَاتَ يَوْمٍ سَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ فَوَجَدْتُ فِي نَفْسِي فَلَمَّا فَرَغَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي إِذَا كُنْتُ سَلَّمْتُ عَلَيْكَ فِي الصَّلَاةِ رَدَدْتَ عَلَيَّ قَالَ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يُحْدِثُ ‏ ‏فِي أَمْرِهِ مَا يَشَاءُ ‏","","",""],[3692,3692,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُؤَاخَذُ أَحَدُنَا بِمَا عَمِلَ فِي الْجَاهِلِيَّةِ قَالَ ‏ ‏مَنْ أَحْسَنَ فِي الْإِسْلَامِ لَمْ يُؤَاخَذْ بِمَا عَمِلَ فِي الْجَاهِلِيَّةِ وَمَنْ أَسَاءَ فِي الْإِسْلَامِ أُخِذَ بِالْأَوَّلِ وَالْآخِرِ ‏","","",""],[3693,3693,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَا نَسِيتُ فِيمَا نَسِيتُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ وَعَنْ يَسَارِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ أَيْضًا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَالثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏أَبِي الضُّحَى ‏","","",""],[3694,3694,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَيْفَ بِكَ يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏إِذَا كَانَ عَلَيْكُمْ أُمَرَاءُ يُضَيِّعُونَ السُّنَّةَ وَيُؤَخِّرُونَ الصَّلَاةَ عَنْ مِيقَاتِهَا قَالَ كَيْفَ تَأْمُرُنِي يَا رَسُولَ اللَّهِ قَالَ تَسْأَلُنِي ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏ ‏كَيْفَ تَفْعَلُ ‏ ‏لَا طَاعَةَ لِمَخْلُوقٍ فِي مَعْصِيَةِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3695,3695,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏الْوَلِيدُ بْنُ الْعَيْزَارِ بْنِ حُرَيْثٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَاحِبُ هَذِهِ الدَّارِ وَأَشَارَ إِلَى دَارِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَلَمْ يُسَمِّهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْعَمَلِ ‏ ‏أَحَبُّ إِلَى اللَّهِ قَالَ ‏ ‏الصَّلَاةُ عَلَى وَقْتِهَا قَالَ قُلْتُ ثُمَّ أَيٌّ قَالَ ثُمَّ ‏ ‏بِرُّ ‏ ‏الْوَالِدَيْنِ قَالَ قُلْتُ ثُمَّ أَيٌّ قَالَ ثُمَّ الْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ فَحَدَّثَنِي بِهِنَّ وَلَوْ اسْتَزَدْتُهُ لَزَادَنِي ‏","","",""],[3696,3696,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي فَلَمَّا نَزَلَتْ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏قَالَ ‏ ‏سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي إِنَّكَ أَنْتَ التَّوَّابُ ‏","","",""],[3697,3697,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ الْأَسَدِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ صَاحِبَكُمْ خَلِيلُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3698,3698,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏حَجَجْنَا مَعَ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏فِي خِلَافَةِ ‏ ‏عُثْمَانَ ‏ ‏قَالَ فَلَمَّا وَقَفْنَا ‏ ‏بِعَرَفَةَ ‏ ‏قَالَ فَلَمَّا غَابَتْ الشَّمْسُ قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏لَوْ أَنَّ أَمِيرَ الْمُؤْمِنِينَ ‏ ‏أَفَاضَ ‏ ‏الْآنَ كَانَ قَدْ أَصَابَ قَالَ فَلَا أَدْرِي كَلِمَةُ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏كَانَتْ أَسْرَعَ أَوْ ‏ ‏إِفَاضَةُ ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏فَأَوْضَعَ ‏ ‏النَّاسُ وَلَمْ يَزِدْ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏عَلَى ‏ ‏الْعَنَقِ ‏ ‏حَتَّى أَتَيْنَا ‏ ‏جَمِيعًا ‏ ‏فَصَلَّى بِنَا ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏الْمَغْرِبَ ثُمَّ دَعَا بِعَشَائِهِ ثُمَّ تَعَشَّى ‏ ‏ثُمَّ قَامَ فَصَلَّى الْعِشَاءَ الْآخِرَةَ ثُمَّ رَقَدَ حَتَّى إِذَا طَلَعَ أَوَّلُ الْفَجْرِ قَامَ فَصَلَّى ‏ ‏الْغَدَاةَ ‏ ‏قَالَ فَقُلْتُ لَهُ مَا كُنْتَ تُصَلِّي الصَّلَاةَ هَذِهِ السَّاعَةَ قَالَ وَكَانَ ‏ ‏يُسْفِرُ ‏ ‏بِالصَّلَاةِ قَالَ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْيَوْمِ وَهَذَا الْمَكَانِ ‏ ‏يُصَلِّي هَذِهِ السَّاعَةَ ‏","","",""],[3699,3699,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَدَبَ ‏ ‏إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّمَرَ ‏ ‏بَعْدَ الْعِشَاءِ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏مَعْنَى ‏ ‏جَدَبَ ‏ ‏إِلَيْنَا يَقُولُ عَابَهُ ذَمَّهُ ‏","","",""],[3700,3700,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي الرَّكْعَتَيْنِ الْأُوَلَتَيْنِ كَأَنَّهُ عَلَى ‏ ‏الرَّضْفِ ‏ ‏قُلْتُ حَتَّى يَقُومَ قَالَ حَتَّى يَقُومَ ‏","","",""],[3701,3701,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَقُولُ إِنَّ الْكَذِبَ لَا يَصْلُحُ مِنْهُ جِدٌّ وَلَا ‏ ‏هَزْلٌ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً جِدٌّ ‏ ‏وَلَا يَعِدُ الرَّجُلُ صَبِيًّا ثُمَّ لَا يُنْجِزُ لَهُ قَالَ وَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏قَالَ لَنَا ‏ ‏لَا يَزَالُ الرَّجُلُ يَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقًا وَلَا يَزَالُ الرَّجُلُ يَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا ‏","","",""],[3702,3702,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ تَغْلِبَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏ذَكَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ ‏","","",""],[3703,3703,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عُثْمَانَ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏حَرْثٍ ‏ ‏مُتَوَكِّئًا عَلَى ‏ ‏عَسِيبٍ ‏ ‏فَقَامَ إِلَيْهِ ‏ ‏نَفَرٌ ‏ ‏مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَسَأَلُوهُ عَنْ الرُّوحِ فَسَكَتَ ثُمَّ تَلَا هَذِهِ الْآيَةَ عَلَيْهِمْ ‏ { ‏يَسْأَلُونَكَ عَنْ الرُّوحِ قُلْ الرُّوحُ مِنْ أَمْرِ رَبِّي وَمَا أُوتِيتُمْ مِنْ الْعِلْمِ إِلَّا قَلِيلًا ‏}","","",""],[3704,3704,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ آخِرُ مَنْ يَدْخُلُ الْجَنَّةَ رَجُلٌ فَهُوَ يَمْشِي مَرَّةً ‏ ‏وَيَكْبُو ‏ ‏مَرَّةً ‏ ‏وَتَسْقَفُهُ ‏ ‏النَّارُ مَرَّةً فَإِذَا جَاوَزَهَا الْتَفَتَ إِلَيْهَا فَقَالَ تَبَارَكَ الَّذِي أَنْجَانِي مِنْكِ لَقَدْ أَعْطَانِي اللَّهُ شَيْئًا مَا أَعْطَاهُ أَحَدًا مِنْ الْأَوَّلِينَ وَالْآخِرِينَ فَتُرْفَعُ لَهُ شَجَرَةٌ فَيَقُولُ أَيْ رَبِّ أَدْنِنِي مِنْ هَذِهِ الشَّجَرَةِ فَأَسْتَظِلَّ بِظِلِّهَا فَأَشْرَبَ مِنْ مَائِهَا فَيَقُولُ لَهُ اللَّهُ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏فَلَعَلِّي إِذَا أَعْطَيْتُكَهَا سَأَلْتَنِي غَيْرَهَا فَيَقُولُ لَا يَا رَبِّ وَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا قَالَ وَرَبُّهُ عَزَّ وَجَلَّ يَعْذُرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهِ ‏ ‏فَيُدْنِيهِ ‏ ‏مِنْهَا فَيَسْتَظِلُّ بِظِلِّهَا وَيَشْرَبُ مِنْ مَائِهَا ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ ‏ ‏هِيَ أَحْسَنُ مِنْ الْأُولَى فَيَقُولُ أَيْ رَبِّ هَذِهِ فَلْأَشْرَبْ مِنْ مَائِهَا وَأَسْتَظِلَّ بِظِلِّهَا لَا أَسْأَلُكَ غَيْرَهَا فَيَقُولُ ابْنَ ‏ ‏آدَمَ ‏ ‏أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا فَيَقُولُ لَعَلِّي إِنْ أَدْنَيْتُكَ مِنْهَا تَسْأَلُنِي غَيْرَهَا فَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا وَرَبُّهُ عَزَّ وَجَلَّ يَعْذُرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهِ ‏ ‏فَيُدْنِيهِ ‏ ‏مِنْهَا فَيَسْتَظِلُّ بِظِلِّهَا وَيَشْرَبُ مِنْ مَائِهَا ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ عِنْدَ بَابِ الْجَنَّةِ هِيَ أَحْسَنُ مِنْ الْأُولَيَيْنِ فَيَقُولُ أَيْ رَبِّ أَدْنِنِي مِنْ هَذِهِ الشَّجَرَةِ فَأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا لَا أَسْأَلُكَ غَيْرَهَا فَيَقُولُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا قَالَ بَلَى أَيْ رَبِّ هَذِهِ لَا أَسْأَلُكَ غَيْرَهَا فَيَقُولُ لَعَلِّي إِنْ أَدْنَيْتُكَ مِنْهَا تَسْأَلُنِي غَيْرَهَا فَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا وَرَبُّهُ يَعْذُرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهِ ‏ ‏فَيُدْنِيهِ ‏ ‏مِنْهَا فَإِذَا أَدْنَاهُ مِنْهَا سَمِعَ أَصْوَاتَ أَهْلِ الْجَنَّةِ فَيَقُولُ أَيْ رَبِّ أَدْخِلْنِيهَا فَيَقُولُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا ‏ ‏يَصْرِينِي مِنْكَ ‏ ‏أَيُرْضِيكَ أَنْ أُعْطِيَكَ الدُّنْيَا وَمِثْلَهَا مَعَهَا فَيَقُولُ أَيْ رَبِّ أَتَسْتَهْزِئُ بِي وَأَنْتَ رَبُّ الْعَالَمِينَ فَضَحِكَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏فَقَالَ أَلَا تَسْأَلُونِي مِمَّا أَضْحَكُ فَقَالُوا مِمَّ تَضْحَكُ فَقَالَ هَكَذَا ضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَلَا تَسْأَلُونِي مِمَّ أَضْحَكُ فَقَالُوا مِمَّ تَضْحَكُ يَا رَسُولَ اللَّهِ قَالَ مِنْ ضَحِكِ رَبِّي حِينَ قَالَ أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ رَبُّ الْعَالَمِينَ فَيَقُولُ إِنِّي لَا أَسْتَهْزِئُ مِنْكَ وَلَكِنِّي عَلَى مَا أَشَاءُ قَدِيرٌ ‏","","",""],[3705,3705,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[3706,3706,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏كُلُّ ثَلَاثَةٍ عَلَى بَعِيرٍ كَانَ ‏ ‏أَبُو لُبَابَةَ ‏ ‏وَعَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏زَمِيلَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَكَانَتْ ‏ ‏عُقْبَةُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَا نَحْنُ نَمْشِي عَنْكَ فَقَالَ ‏ ‏مَا أَنْتُمَا بِأَقْوَى مِنِّي وَلَا أَنَا بِأَغْنَى عَنْ الْأَجْرِ مِنْكُمَا ‏","","",""],[3707,3707,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِسْمَةً فَقَالَ رَجُلٌ مِنْ الْقَوْمِ إِنَّ هَذِهِ الْقِسْمَةَ مَا يُرَادُ بِهَا وَجْهُ اللَّهِ عَزَّ وَجَلَّ قَالَ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثْتُهُ قَالَ فَغَضِبَ حَتَّى رَأَيْتُ الْغَضَبَ فِي وَجْهِهِ فَقَالَ ‏ ‏يَرْحَمُ اللَّهُ ‏ ‏مُوسَى ‏ ‏قَدْ أُوذِيَ بِأَكْثَرَ مِنْ ذَلِكَ فَصَبَرَ ‏","","",""],[3708,3708,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏زُبَيْدٌ ‏ ‏وَمَنْصُورٌ ‏ ‏وَسُلَيْمَانُ ‏ ‏أَخْبَرُونِي أَنَّهُمْ سَمِعُوا ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ كُفْرٌ ‏ ‏قَالَ ‏ ‏زُبَيْدٌ ‏ ‏فَقُلْتُ ‏ ‏لِأَبِي وَائِلٍ ‏ ‏مَرَّتَيْنِ أَأَنْتَ سَمِعْتَهُ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[3709,3709,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَخْبَرَنَا قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ التُّقَى وَالْهُدَى ‏ ‏وَالْعَفَافَ ‏ ‏وَالْغِنَى ‏","","",""],[3710,3710,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مَسْعُودُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَتَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏صَدَقَةِ ‏ ‏الْبَقَرِ إِذَا بَلَغَ الْبَقَرُ ثَلَاثِينَ فَفِيهَا تَبِيعٌ مِنْ الْبَقَرِ ‏ ‏جَذَعٌ ‏ ‏أَوْ ‏ ‏جَذَعَةٌ ‏ ‏حَتَّى تَبْلُغَ أَرْبَعِينَ فَإِذَا بَلَغَتْ أَرْبَعِينَ فَفِيهَا بَقَرَةٌ ‏ ‏مُسِنَّةٌ ‏ ‏فَإِذَا كَثُرَتْ الْبَقَرُ فَفِي كُلِّ أَرْبَعِينَ مِنْ الْبَقَرِ بَقَرَةٌ ‏ ‏مُسِنَّةٌ ‏","","",""],[3711,3711,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏فَقَالَ لَقَدْ ‏ ‏أَخَذْتُ مِنْ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِضْعًا ‏ ‏وَسَبْعِينَ سُورَةً ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏غُلَامٌ لَهُ ‏ ‏ذُؤَابَتَانِ ‏ ‏يَلْعَبُ مَعَ الْغِلْمَانِ ‏","","",""],[3712,3712,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ مَيْسَرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النَّزَّالَ بْنَ سَبْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَجُلًا يَقْرَأُ آيَةً عَلَى غَيْرِ مَا أَقْرَأَنِيهَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذْتُ بِيَدِهِ حَتَّى ذَهَبْتُ بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كِلَاكُمَا مُحْسِنٌ لَا تَخْتَلِفُوا أَكْبَرُ عِلْمِي وَإِلَّا ‏ ‏فَمِسْعَرٌ ‏ ‏حَدَّثَنِي بِهَا فَإِنَّ مَنْ قَبْلَكُمْ اخْتَلَفُوا فِيهِ فَهَلَكُوا ‏","","",""],[3713,3713,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ مَيْسَرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النَّزَّالَ بْنَ سَبْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا يَقْرَأُ آيَةً عَلَى غَيْرِ مَا أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذْتُ بِيَدِهِ فَأَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏كِلَاكُمَا قَدْ أَحْسَنَ قَالَ وَغَضِبَ حَتَّى عُرِفَ الْغَضَبُ فِي وَجْهِهِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَكْبَرُ ظَنِّي أَنَّهُ قَالَ لَا تَخْتَلِفُوا فَإِنَّ مَنْ قَبْلَكُمْ اخْتَلَفُوا فِيهِ فَهَلَكُوا ‏","","",""],[3714,3714,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَحْوَصِ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَقُولُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ مُتَّخِذًا خَلِيلًا مِنْ أُمَّتِي لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏","","",""],[3715,3715,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏قَالَ ‏ ‏لِابْنِ مَسْعُودٍ ‏ ‏كَيْفَ تَعْرِفُ هَذَا الْحَرْفَ مَاءٌ غَيْرُ ‏ ‏يَاسِنٍ ‏ ‏أَمْ ‏ ‏آسِنٍ ‏ ‏فَقَالَ كُلَّ الْقُرْآنِ قَدْ قَرَأْتَ قَالَ إِنِّي لَأَقْرَأُ ‏ ‏الْمُفَصَّلَ ‏ ‏أَجْمَعَ فِي رَكْعَةٍ وَاحِدَةٍ فَقَالَ أَهَذَّ الشِّعْرِ لَا أَبَا لَكَ قَدْ ‏ ‏عَلِمْتُ ‏ ‏قَرَائِنَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّتِي كَانَ ‏ ‏يَقْرُنُ ‏ ‏قَرِينَتَيْنِ قَرِينَتَيْنِ مِنْ أَوَّلِ ‏ ‏الْمُفَصَّلِ ‏ ‏وَكَانَ أَوَّلُ ‏ ‏مُفَصَّلِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏الرَّحْمَنُ ‏","","",""],[3716,3716,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنِ ‏ ‏ابْنِ أُذْنَانَ ‏ ‏قَالَ ‏ ‏أَسْلَفْتُ ‏ ‏عَلْقَمَةَ ‏ ‏أَلْفَيْ دِرْهَمٍ فَلَمَّا خَرَجَ عَطَاؤُهُ قُلْتُ لَهُ اقْضِنِي قَالَ أَخِّرْنِي إِلَى ‏ ‏قَابِلٍ ‏ ‏فَأَتَيْتُ عَلَيْهِ فَأَخَذْتُهَا قَالَ فَأَتَيْتُهُ بَعْدُ قَالَ ‏ ‏بَرَّحْتَ ‏ ‏بِي قَدْ مَنَعْتَنِي فَقُلْتُ نَعَمْ هُوَ عَمَلُكَ قَالَ وَمَا شَأْنِي قُلْتُ إِنَّكَ حَدَّثْتَنِي عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏السَّلَفَ ‏ ‏يَجْرِي مَجْرَى ‏ ‏شَطْرِ ‏ ‏الصَّدَقَةِ ‏ ‏قَالَ نَعَمْ فَهُوَ كَذَاكَ قَالَ فَخُذْ الْآنَ ‏","","",""],[3717,3717,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْعَيْنَانِ تَزْنِيَانِ وَالْيَدَانِ تَزْنِيَانِ وَالرِّجْلَانِ تَزْنِيَانِ وَالْفَرْجُ يَزْنِي ‏","","",""],[3718,3718,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنِي ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ أَحَدٌ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةٍ مِنْ كِبْرٍ وَلَا يَدْخُلُ النَّارَ مَنْ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ إِيمَانٍ ‏","","",""],[3719,3719,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏أَهْلِ الصُّفَّةِ ‏ ‏مَاتَ فَوُجِدَ فِي بُرْدَتِهِ دِينَارَانِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيَّتَانِ ‏","","",""],[3720,3720,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ فِي هَذِهِ الْآيَةِ ‏ { ‏وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى ‏} ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ ‏ ‏جِبْرِيلَ ‏ ‏عِنْدَ سِدْرَةِ الْمُنْتَهَى عَلَيْهِ سِتُّ مِائَةِ جَنَاحٍ يُنْثَرُ مِنْ رِيشِهِ التَّهَاوِيلُ الدُّرُّ وَالْيَاقُوتُ ‏","","",""],[3721,3721,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ اللَّهُمَّ ‏ ‏فَاطِرَ ‏ ‏السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ إِنِّي أَعْهَدُ إِلَيْكَ فِي هَذِهِ الْحَيَاةِ الدُّنْيَا أَنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُكَ وَرَسُولُكَ فَإِنَّكَ إِنْ تَكِلْنِي إِلَى نَفْسِي تُقَرِّبْنِي مِنْ الشَّرِّ وَتُبَاعِدْنِي مِنْ الْخَيْرِ وَإِنِّي لَا أَثِقُ إِلَّا بِرَحْمَتِكَ فَاجْعَلْ لِي عِنْدَكَ عَهْدًا ‏ ‏تُوَفِّينِيهِ يَوْمَ الْقِيَامَةِ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ إِلَّا قَالَ اللَّهُ لِمَلَائِكَتِهِ يَوْمَ الْقِيَامَةِ إِنَّ عَبْدِي قَدْ عَهِدَ إِلَيَّ عَهْدًا فَأَوْفُوهُ إِيَّاهُ فَيُدْخِلُهُ اللَّهُ الْجَنَّةَ ‏ ‏قَالَ ‏ ‏سُهَيْلٌ ‏ ‏فَأَخْبَرْتُ ‏ ‏الْقَاسِمَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَوْنًا ‏ ‏أَخْبَرَ بِكَذَا وَكَذَا قَالَ مَا فِي أَهْلِنَا ‏ ‏جَارِيَةٌ ‏ ‏إِلَّا وَهِيَ تَقُولُ هَذَا فِي ‏ ‏خِدْرِهَا ‏","","",""],[3722,3722,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏مَنْصُورٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏سَمَرَ ‏ ‏إِلَّا لِأَحَدِ رَجُلَيْنِ لِمُصَلٍّ أَوْ مُسَافِرٍ ‏","","",""],[3723,3723,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَسْوَدَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقْرَأُ هَذَا الْحَرْفَ ‏ { ‏فَهَلْ مِنْ ‏ ‏مُدَّكِرٍ ‏ } ‏بِالدَّالِ ‏","","",""],[3724,3724,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا صَلَّيْنَا خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ الرَّجُلُ مِنَّا فِي صَلَاتِهِ السَّلَامُ عَلَى اللَّهِ السَّلَامُ عَلَى فُلَانٍ يَخُصُّ فَقَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ هُوَ السَّلَامُ فَإِذَا قَعَدَ أَحَدُكُمْ فِي صَلَاتِهِ فَلْيَقُلْ التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ فَإِذَا قُلْتُمْ ذَلِكَ فَقَدْ سَلَّمْتُمْ عَلَى كُلِّ عَبْدٍ فِي السَّمَوَاتِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ يَتَخَيَّرُ بَعْدُ مِنْ الدُّعَاءِ مَا شَاءَ ‏ ‏أَوْ مَا أَحَبَّ ‏","","",""],[3725,3725,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا قَعَدْنَا فِي الصَّلَاةِ قُلْنَا السَّلَامُ عَلَى اللَّهِ السَّلَامُ عَلَيْنَا مِنْ رَبِّنَا السَّلَامُ عَلَى ‏ ‏جِبْرِيلَ ‏ ‏وَمِيكَائِيلَ ‏ ‏السَّلَامُ عَلَى فُلَانٍ السَّلَامُ عَلَى فُلَانٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ هُوَ السَّلَامُ فَإِذَا قَعَدْتُمْ فِي الصَّلَاةِ فَقُولُوا التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ فَإِنَّهُ إِذَا قَالَ ذَلِكَ أَصَابَتْ كُلَّ عَبْدٍ صَالِحٍ فِي السَّمَاءِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ يَتَخَيَّرُ مِنْ الْكَلَامِ مَا شَاءَ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏وَحَدَّثَنِيهِ ‏ ‏أَيْضًا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏بِمِثْلِهِ ‏","","",""],[3726,3726,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏وَأَبِي الْأَحْوَصِ ‏ ‏وَأَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا التَّشَهُّدَ فِي الصَّلَاةِ التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏","","",""],[3727,3727,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ يَعْنِي ابْنَ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ دَاءً إِلَّا أَنْزَلَ لَهُ دَوَاءً عَلِمَهُ مَنْ عَلِمَهُ وَجَهِلَهُ مَنْ جَهِلَهُ ‏","","",""],[3728,3728,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ ‏ ‏شِرَاكِ ‏ ‏نَعْلِهِ وَالنَّارُ مِثْلُ ذَلِكَ ‏","","",""],[3729,3729,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏انْشَقَّ ‏ ‏الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى رَأَيْتُ الْجَبَلَ مِنْ بَيْنِ فُرْجَتَيْ الْقَمَرِ ‏","","",""],[3730,3730,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ الْيَشْكُرِيِّ ‏ ‏عَنِ ‏ ‏الْمَعْرُورِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أُمُّ حَبِيبَةَ ‏ ‏اللَّهُمَّ مَتِّعْنِي بِزَوْجِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِأَبِي ‏ ‏أَبِي سُفْيَانَ ‏ ‏وَبِأَخِي ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكِ سَأَلْتِ اللَّهَ لِآجَالٍ ‏ ‏مَضْرُوبَةٍ ‏ ‏وَأَرْزَاقٍ مَقْسُومَةٍ وَآثَارٍ مَبْلُوغَةٍ لَا يُعَجَّلُ مِنْهَا شَيْءٌ قَبْلَ ‏ ‏حِلِّهِ ‏ ‏وَلَا يُؤَخَّرُ مِنْهَا شَيْءٌ بَعْدَ ‏ ‏حِلِّهِ ‏ ‏وَلَوْ سَأَلْتِ اللَّهَ أَنْ يُعَافِيَكِ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ كَانَ خَيْرًا لَكِ ‏","","",""],[3731,3731,"","","‏ ‏قَالَ ‏ ‏فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ الْقِرَدَةُ وَالْخَنَازِيرُ هِيَ مِمَّا ‏ ‏مُسِخَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ ‏ ‏يَمْسَخْ ‏ ‏اللَّهُ قَوْمًا أَوْ يُهْلِكْ قَوْمًا فَيَجْعَلَ لَهُمْ نَسْلًا وَلَا ‏ ‏عَاقِبَةً ‏ ‏وَإِنَّ الْقِرَدَةَ وَالْخَنَازِيرَ قَدْ كَانَتْ قَبْلَ ذَلِكَ ‏","","",""],[3732,3732,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏قَالَ ‏ ‏ذَكَرَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَيَّ الشَّيْطَانُ فَأَخَذْتُهُ فَخَنَقْتُهُ حَتَّى إِنِّي لَأَجِدُ بَرْدَ لِسَانِهِ فِي يَدَيَّ فَقَالَ أَوْجَعْتَنِي أَوْجَعْتَنِي ‏","","",""],[3733,3733,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏ابْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏وَالْأَسْوَدِ ‏ ‏أَنَّهُمَا كَانَا مَعَ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏فَحَضَرَتْ الصَّلَاةُ فَتَأَخَّرَ ‏ ‏عَلْقَمَةُ ‏ ‏وَالْأَسْوَدُ ‏ ‏فَأَخَذَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏بِأَيْدِيهِمَا فَأَقَامَ أَحَدَهُمَا عَنْ يَمِينِهِ وَالْآخَرَ عَنْ يَسَارِهِ ثُمَّ رَكَعَا فَوَضَعَا أَيْدِيَهُمَا عَلَى رُكَبِهِمَا وَضَرَبَ أَيْدِيَهُمَا ثُمَّ ‏ ‏طَبَّقَ ‏ ‏بَيْنَ يَدَيْهِ وَشَبَّكَ وَجَعَلَهُمَا بَيْنَ فَخِذَيْهِ وَقَالَ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَهُ ‏ ‏حَدَّثَنَاه ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏وَعَلْقَمَةَ بْنِ قَيْسٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[3734,3734,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏خُمَيْرِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُمِرَ بِالْمَصَاحِفِ أَنْ ‏ ‏تُغَيَّرَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ أَنْ ‏ ‏يَغُلَّ ‏ ‏مُصْحَفَهُ ‏ ‏فَلْيَغُلَّهُ ‏ ‏فَإِنَّ مَنْ ‏ ‏غَلَّ ‏ ‏شَيْئًا جَاءَ بِهِ يَوْمَ الْقِيَامَةِ قَالَ ثُمَّ قَالَ ‏ ‏قَرَأْتُ مِنْ فَمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعِينَ سُورَةً أَفَأَتْرُكُ مَا أَخَذْتُ مِنْ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3735,3735,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏قَالَ وَأَخْبَرَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏صِلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏الْعَاقِبُ ‏ ‏وَالسَّيِّدُ ‏ ‏صَاحِبَا ‏ ‏نَجْرَانَ ‏ ‏قَالَ وَأَرَادَا أَنْ يُلَاعِنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ لَا تُلَاعِنْهُ فَوَاللَّهِ لَئِنْ كَانَ نَبِيًّا فَلَعَنَّا ‏ ‏قَالَ ‏ ‏خَلَفٌ ‏ ‏فَلَاعَنَّا ‏ ‏لَا نُفْلِحُ نَحْنُ وَلَا ‏ ‏عَقِبُنَا ‏ ‏أَبَدًا قَالَ فَأَتَيَاهُ فَقَالَا لَا نُلَاعِنُكَ وَلَكِنَّا ‏ ‏نُعْطِيكَ مَا سَأَلْتَ فَابْعَثْ مَعَنَا رَجُلًا أَمِينًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَبْعَثَنَّ رَجُلًا أَمِينًا حَقَّ أَمِينٍ حَقَّ أَمِينٍ قَالَ ‏ ‏فَاسْتَشْرَفَ ‏ ‏لَهَا ‏ ‏أَصْحَابُ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ فَقَالَ قُمْ يَا ‏ ‏أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ ‏ ‏قَالَ فَلَمَّا ‏ ‏قَفَّا ‏ ‏قَالَ هَذَا أَمِينُ هَذِهِ الْأُمَّةِ ‏","","",""],[3736,3736,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَأَبُو أَحْمَدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَامَ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏إِذَا ‏ ‏أَوَى ‏ ‏إِلَى فِرَاشِهِ ‏ ‏وَضَعَ يَدَهُ الْيُمْنَى تَحْتَ خَدِّهِ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏الْأَيْمَنِ ‏ ‏ثُمَّ قَالَ ‏ ‏اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَجْمَعُ عِبَادَكَ ‏ ‏حَدَّثَنَاه ‏ ‏وَكِيعٌ ‏ ‏بِمَعْنَاهُ ‏","","",""],[3737,3737,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُسَلِّمُ فِي صَلَاتِهِ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ حَتَّى يُرَى بَيَاضُ خَدَّيْهِ ‏","","",""],[3738,3738,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏فِطْرٌ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَهُوَ ‏ ‏الصَّادِقُ الْمَصْدُوقُ ‏ ‏يُجْمَعُ خَلْقُ أَحَدِكُمْ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ لَيْلَةً ثُمَّ يَكُونُ ‏ ‏عَلَقَةً ‏ ‏مِثْلَ ذَلِكَ ثُمَّ يَكُونُ ‏ ‏مُضْغَةً ‏ ‏مِثْلَ ذَلِكَ ثُمَّ يَبْعَثُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ مَلَكًا مِنْ الْمَلَائِكَةِ فَيَقُولُ اكْتُبْ عَمَلَهُ وَأَجَلَهُ وَرِزْقَهُ وَاكْتُبْهُ شَقِيًّا أَوْ سَعِيدًا ثُمَّ قَالَ وَالَّذِي نَفْسُ ‏ ‏عَبْدِ اللَّهِ ‏ ‏بِيَدِهِ إِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَ الْجَنَّةِ غَيْرُ ذِرَاعٍ ثُمَّ يُدْرِكُهُ الشَّقَاءُ فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ فَيَمُوتُ فَيَدْخُلُ النَّارَ ثُمَّ قَالَ وَالَّذِي نَفْسُ ‏ ‏عَبْدِ اللَّهِ ‏ ‏بِيَدِهِ إِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَ النَّارِ غَيْرُ ذِرَاعٍ ثُمَّ تُدْرِكُهُ السَّعَادَةُ فَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ فَيَمُوتُ فَيَدْخُلُ الْجَنَّةَ ‏","","",""],[3739,3739,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سَيْفٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَخْبَرَةَ أَبُو مَعْمَرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏عَلَّمَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّشَهُّدَ كَفِّي بَيْنَ كَفَّيْهِ كَمَا يُعَلِّمُنِي السُّورَةَ مِنْ الْقُرْآنِ قَالَ ‏ ‏التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ وَهُوَ بَيْنَ ظَهْرَانَيْنَا فَلَمَّا قُبِضَ قُلْنَا السَّلَامُ عَلَى النَّبِيِّ ‏","","",""],[3740,3740,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُمَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ الْأَقْمَرِ ‏ ‏يَذْكُرُ عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ سَرَّهُ أَنْ يَلْقَى اللَّهَ غَدًا مُسْلِمًا فَلْيُحَافِظْ عَلَى هَؤُلَاءِ الصَّلَوَاتِ ‏ ‏حَيْثُ يُنَادَى بِهِنَّ ‏ ‏فَإِنَّ اللَّهَ شَرَعَ لِنَبِيِّكُمْ سُنَنَ ‏ ‏الْهُدَى ‏ ‏وَإِنَّهُنَّ مِنْ سُنَنِ ‏ ‏الْهُدَى ‏ ‏وَلَوْ أَنَّكُمْ صَلَّيْتُمْ فِي بُيُوتِكُمْ كَمَا ‏ ‏يُصَلِّي هَذَا الْمُتَخَلِّفُ فِي بَيْتِهِ لَتَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ وَلَوْ أَنَّكُمْ تَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ لَضَلَلْتُمْ وَمَا مِنْ رَجُلٍ يَتَطَهَّرُ فَيُحْسِنُ الطُّهُورَ ثُمَّ ‏ ‏يَعْمِدُ ‏ ‏إِلَى مَسْجِدٍ مِنْ هَذِهِ الْمَسَاجِدِ إِلَّا كَتَبَ اللَّهُ لَهُ بِكُلِّ خُطْوَةٍ ‏ ‏يَخْطُوهَا حَسَنَةً وَيَرْفَعُ لَهُ بِهَا دَرَجَةً وَيَحُطُّ عَنْهُ بِهَا سَيِّئَةً وَلَوْ رَأَيْتُنَا وَمَا يَتَخَلَّفُ عَنْهَا إِلَّا مُنَافِقٌ مَعْلُومُ النِّفَاقِ وَلَقَدْ كَانَ الرَّجُلُ يُؤْتَى بِهِ ‏ ‏يُهَادَى ‏ ‏بَيْنَ الرَّجُلَيْنِ حَتَّى يُقَامَ فِي الصَّفِّ ‏","","",""],[3741,3741,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ لَيْلَةً مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَزَلْ قَائِمًا حَتَّى هَمَمْتُ بِأَمْرِ سُوءٍ قُلْنَا وَمَا هَمَمْتَ بِهِ قَالَ هَمَمْتُ أَنْ أَقْعُدَ وَأَدَعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏وَحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏مِثْلَهُ ‏","","",""],[3742,3742,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ الْجُمَحِيَّ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏الْأَوْدِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُرِّمَ عَلَى النَّارِ كُلُّ هَيِّنٍ لَيِّنٍ سَهْلٍ قَرِيبٍ مِنْ النَّاسِ ‏","","",""],[3743,3743,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الْحَارِثِ يَحْيَى التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَاجِدٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلْنَا نَبِيَّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السَّيْرِ بِالْجِنَازَةِ فَقَالَ ‏ ‏السَّيْرُ مَا دُونَ ‏ ‏الْخَبَبِ ‏ ‏فَإِنْ يَكُ خَيْرًا يُعَجَّلْ ‏ ‏أَوْ تُعَجَّلْ إِلَيْهِ ‏ ‏وَإِنْ يَكُ سِوَى ذَلِكَ فَبُعْدًا لِأَهْلِ النَّارِ الْجِنَازَةُ مَتْبُوعَةٌ وَلَا تَتْبَعُ لَيْسَ مِنَّا مَنْ تَقَدَّمَهَا ‏","","",""],[3744,3744,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَوْنُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا حُدِّثْتُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا فَظُنُّوا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي هُوَ أَهْيَاهُ وَأَهْدَاهُ وَأَتْقَاهُ ‏","","",""],[3745,3745,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏أَنَّهُ حَجَّ مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏فَرَمَى ‏ ‏الْجَمْرَةَ الْكُبْرَى ‏ ‏بِسَبْعِ حَصَيَاتٍ وَجَعَلَ ‏ ‏الْبَيْتَ ‏ ‏عَنْ يَسَارِهِ ‏ ‏وَمِنًى ‏ ‏عَنْ يَمِينِهِ وَقَالَ هَذَا مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[3746,3746,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏اسْتَبْطَنَ ‏ ‏الْوَادِيَ ‏ ‏وَاعْتَرَضَ ‏ ‏الْجِمَارَ ‏ ‏اعْتِرَاضًا وَجَعَلَ الْجَبَلَ فَوْقَ ظَهْرِهِ ثُمَّ رَمَى وَقَالَ هَذَا مَقَامُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[3747,3747,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَحِقَ بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدٌ أَسْوَدُ فَمَاتَ فَأُتِيَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏انْظُرُوا هَلْ تَرَكَ شَيْئًا قَالُوا تَرَكَ دِينَارَيْنِ قَالَ كَيَّتَانِ ‏","","",""],[3748,3748,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏وَابْنُ فُضَيْلٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏أَبِي الْجَهْمِ ‏ ‏عَنْ ‏ ‏أَبِي الرَّضْرَاضِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أُسَلِّمُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الصَّلَاةِ فَيَرُدُّ عَلَيَّ فَسَلَّمْتُ عَلَيْهِ ذَاتَ يَوْمٍ فَلَمْ يَرُدَّ عَلَيَّ شَيْئًا فَوَجَدْتُ فِي نَفْسِي فَقُلْتُ يَا رَسُولَ اللَّهِ كُنْتُ أُسَلِّمُ عَلَيْكَ وَأَنْتَ فِي الصَّلَاةِ فَتَرُدُّ عَلَيَّ وَإِنِّي سَلَّمْتُ عَلَيْكَ فَلَمْ تَرُدَّ عَلَيَّ شَيْئًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يُحْدِثُ فِي أَمْرِهِ مَا يَشَاءُ ‏","","",""],[3749,3749,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏أَنْبَأَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَزْرَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ الْعُرَنِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الجَزَّارِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏أَنَّ امْرَأَةً جَاءَتْ إِلَى ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏فَقَالَتْ أُنْبِئْتُ أَنَّكَ ‏ ‏تَنْهَى عَنْ ‏ ‏الْوَاصِلَةِ ‏ ‏قَالَ نَعَمْ فَقَالَتْ أَشَيْءٌ تَجِدُهُ فِي كِتَابِ اللَّهِ أَمْ سَمِعْتَهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَجِدُهُ فِي كِتَابِ اللَّهِ وَعَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ وَاللَّهِ لَقَدْ تَصَفَّحْتُ مَا بَيْنَ دَفَّتَيْ الْمُصْحَفِ فَمَا وَجَدْتُ فِيهِ الَّذِي تَقُولُ قَالَ فَهَلْ وَجَدْتِ فِيهِ ‏ { ‏مَا آتَاكُمْ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا ‏} ‏قَالَتْ نَعَمْ قَالَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏النَّامِصَةِ ‏ ‏وَالْوَاشِرَةِ ‏ ‏وَالْوَاصِلَةِ ‏ ‏وَالْوَاشِمَةِ ‏ ‏إِلَّا مِنْ دَاءٍ قَالَتْ الْمَرْأَةُ فَلَعَلَّهُ فِي بَعْضِ نِسَائِكَ قَالَ لَهَا ادْخُلِي فَدَخَلَتْ ثُمَّ خَرَجَتْ فَقَالَتْ مَا رَأَيْتُ بَأْسًا قَالَ مَا حَفِظْتُ إِذًا وَصِيَّةَ الْعَبْدِ الصَّالِحِ ‏ { ‏وَمَا أُرِيدُ أَنْ ‏ ‏أُخَالِفَكُمْ إِلَى مَا ‏ ‏أَنْهَاكُمْ عَنْهُ ‏}","","",""],[3750,3750,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اقْتَطَعَ مَالَ امْرِئٍ مُسْلِمٍ بِغَيْرِ حَقٍّ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهُوَ عَلَيْهِ غَضْبَانُ ‏","","",""],[3751,3751,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ رَجُلٌ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏ذَرَّةٍ مِنْ كِبْرٍ وَلَا يَدْخُلُ النَّارَ رَجُلٌ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏ذَرَّةٍ مِنْ إِيمَانٍ ‏","","",""],[3752,3752,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُؤْمِنَ لَيْسَ ‏ ‏بِاللَّعَّانِ ‏ ‏وَلَا ‏ ‏الطَّعَّانِ ‏ ‏وَلَا ‏ ‏الْفَاحِشِ ‏ ‏وَلَا الْبَذِيءِ ‏","","",""],[3753,3753,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنِ ‏ ‏مُرَّةَ الْهَمْدَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ عَجِبَ رَبُّنَا عَزَّ وَجَلَّ مِنْ رَجُلَيْنِ رَجُلٍ ثَارَ عَنْ وِطَائِهِ وَلِحَافِهِ مِنْ بَيْنِ أَهْلِهِ وَحَيِّهِ إِلَى صَلَاتِهِ فَيَقُولُ رَبُّنَا أَيَا مَلَائِكَتِي ‏ ‏انْظُرُوا إِلَى عَبْدِي ثَارَ مِنْ فِرَاشِهِ وَوِطَائِهِ وَمِنْ بَيْنِ حَيِّهِ وَأَهْلِهِ إِلَى صَلَاتِهِ رَغْبَةً فِيمَا عِنْدِي وَشَفَقَةً مِمَّا عِنْدِي وَرَجُلٍ غَزَا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَانْهَزَمُوا فَعَلِمَ مَا عَلَيْهِ مِنْ الْفِرَارِ وَمَا لَهُ فِي الرُّجُوعِ فَرَجَعَ حَتَّى ‏ ‏أُهَرِيقَ ‏ ‏دَمُهُ رَغْبَةً فِيمَا عِنْدِي وَشَفَقَةً مِمَّا عِنْدِي فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ لِمَلَائِكَتِهِ انْظُرُوا إِلَى عَبْدِي رَجَعَ رَغْبَةً فِيمَا عِنْدِي وَرَهْبَةً مِمَّا عِنْدِي حَتَّى ‏ ‏أُهَرِيقَ ‏ ‏دَمُهُ ‏","","",""],[3754,3754,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَحْوَصِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَدْعُو بِهَذَا الدُّعَاءِ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ ‏ ‏الْهُدَى ‏ ‏وَالتُّقَى ‏ ‏وَالْعَفَافَ ‏ ‏وَالْغِنَى ‏","","",""],[3755,3755,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ابْتَعَثَ نَبِيَّهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِإِدْخَالِ رَجُلٍ إِلَى الْجَنَّةِ فَدَخَلَ الْكَنِيسَةَ فَإِذَا هُوَ ‏ ‏بِيَهُودَ ‏ ‏وَإِذَا يَهُودِيٌّ يَقْرَأُ عَلَيْهِمْ التَّوْرَاةَ فَلَمَّا أَتَوْا عَلَى صِفَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسَكُوا وَفِي نَاحِيَتِهَا رَجُلٌ مَرِيضٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَكُمْ أَمْسَكْتُمْ قَالَ الْمَرِيضُ إِنَّهُمْ أَتَوْا عَلَى صِفَةِ نَبِيٍّ فَأَمْسَكُوا ثُمَّ جَاءَ الْمَرِيضُ ‏ ‏يَحْبُو حَتَّى أَخَذَ التَّوْرَاةَ فَقَرَأَ حَتَّى أَتَى عَلَى صِفَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُمَّتِهِ فَقَالَ هَذِهِ صِفَتُكَ وَصِفَةُ أُمَّتِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّكَ رَسُولُ اللَّهِ ثُمَّ مَاتَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَصْحَابِهِ ‏ ‏لُوا أَخَاكُمْ ‏","","",""],[3756,3756,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ أَنْ تَقُولُوا مَاتَ فُلَانٌ شَهِيدًا أَوْ قُتِلَ فُلَانٌ شَهِيدًا فَإِنَّ الرَّجُلَ يُقَاتِلُ لِيَغْنَمَ وَيُقَاتِلُ لِيُذْكَرَ وَيُقَاتِلُ لِيُرَى مَكَانُهُ فَإِنْ كُنْتُمْ شَاهِدِينَ لَا مَحَالَةَ ‏ ‏فَاشْهَدُوا ‏ ‏لِلرَّهْطِ ‏ ‏الَّذِينَ بَعَثَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَقُتِلُوا فَقَالُوا اللَّهُمَّ ‏ ‏بَلِّغْ ‏ ‏نَبِيَّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنَّا أَنَّا قَدْ لَقِينَاكَ فَرَضِينَا عَنْكَ وَرَضِيتَ عَنَّا ‏","","",""],[3757,3757,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ عُمَيْرٍ ‏ ‏يُحَدِّثُ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏أَوْ ‏ ‏إِبْرَاهِيمَ ‏ ‏شُعْبَةُ ‏ ‏شَكَّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رَكْعَتَيْنِ فَلَيْتَ حَظِّي مِنْ أَرْبَعٍ رَكْعَتَانِ مُتَقَبَّلَتَانِ ‏","","",""],[3758,3758,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بِتُّ اللَّيْلَةَ أَقْرَأُ عَلَى الْجِنِّ رُفَقَاءَ ‏ ‏بِالْحَجُونِ ‏","","",""],[3759,3759,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏وَيَحْيَى بْنُ حَمَّادٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْعُرْيَانِ بْنِ الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ جَابِرٍ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ مَعَ عَجُوزٍ مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏إِلَى ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلْعَنُ ‏ ‏الْمُتَنَمِّصَاتِ ‏ ‏وَالْمُتَفَلِّجَاتِ ‏ ‏وَالْمُوشِمَاتِ ‏ ‏اللَّاتِي يُغَيِّرْنَ خَلْقَ اللَّهِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَالْمُوسِمَاتِ ‏ ‏اللَّاتِي ‏","","",""],[3760,3760,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنِ ‏ ‏الْعُرْيَانِ بْنِ الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ جَابِرٍ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ مَعَ عَجُوزٍ إِلَى ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏فَذَكَرَ قِصَّةً ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلْعَنُ ‏ ‏الْمُتَنَمِّصَاتِ ‏ ‏وَالْمُتَفَلِّجَاتِ ‏ ‏وَالْمُوشِمَاتِ ‏ ‏اللَّاتِي يُغَيِّرْنَ خَلْقَ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3761,3761,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِتَالُ مُسْلِمٍ أَخَاهُ كُفْرٌ وَسِبَابُهُ فُسُوقٌ ‏","","",""],[3762,3762,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏نَهِيكِ بْنِ سِنَانٍ السُّلَمِيِّ ‏ ‏أَنَّهُ أَتَى ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏فَقَالَ قَرَأْتُ ‏ ‏الْمُفَصَّلَ ‏ ‏اللَّيْلَةَ فِي رَكْعَةٍ فَقَالَ هَذًّا مِثْلَ هَذِّ الشِّعْرِ أَوْ ‏ ‏نَثْرًا ‏ ‏مِثْلَ ‏ ‏نَثْرِ ‏ ‏الدَّقَلِ ‏ ‏إِنَّمَا ‏ ‏فُصِّلَ ‏ ‏لِتُفَصِّلُوا لَقَدْ عَلِمْتُ ‏ ‏النَّظَائِرَ ‏ ‏الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرُنُ ‏ ‏عِشْرِينَ سُورَةً ‏ ‏الرَّحْمَنُ ‏ ‏وَالنَّجْمُ ‏ ‏عَلَى تَأْلِيفِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏كُلُّ سُورَتَيْنِ فِي رَكْعَةٍ وَذَكَرَ ‏ ‏الدُّخَانَ ‏ ‏وَعَمَّ يَتَسَاءَلُونَ ‏ ‏فِي رَكْعَةٍ ‏","","",""],[3763,3763,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏سَمِعَ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏وَيُقَالُ هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانٍ ‏","","",""],[3764,3764,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بِئْسَمَا لِأَحَدِكُمْ ‏ ‏أَوْ بِئْسَمَا لِأَحَدِهِمْ ‏ ‏أَنْ يَقُولَ نَسِيتُ آيَةَ كَيْتَ وَكَيْتَ بَلْ هُوَ نُسِّيَ اسْتَذْكِرُوا الْقُرْآنَ فَوَالَّذِي نَفْسِي بِيَدِهِ لَهُوَ أَشَدُّ ‏ ‏تَفَصِّيًا ‏ ‏مِنْ صُدُورِ الرِّجَالِ مِنْ النَّعَمِ مِنْ ‏ ‏عُقُلِهَا ‏","","",""],[3765,3765,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏الْحَارِثُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ سَخْبَرَةَ ‏ ‏قَالَ ‏ ‏غَدَوْتُ مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏مِنْ ‏ ‏مِنًى ‏ ‏إِلَى ‏ ‏عَرَفَاتٍ ‏ ‏فَكَانَ يُلَبِّي قَالَ وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏رَجُلًا ‏ ‏آدَمَ ‏ ‏لَهُ ‏ ‏ضَفْرَانِ ‏ ‏عَلَيْهِ مَسْحَةُ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏فَاجْتَمَعَ عَلَيْهِ ‏ ‏غَوْغَاءُ ‏ ‏مِنْ ‏ ‏غَوْغَاءِ ‏ ‏النَّاسِ قَالُوا يَا أَعْرَابِيُّ إِنَّ هَذَا لَيْسَ يَوْمَ تَلْبِيَةٍ إِنَّمَا هُوَ يَوْمُ تَكْبِيرٍ قَالَ فَعِنْدَ ذَلِكَ الْتَفَتَ إِلَيَّ فَقَالَ أَجَهِلَ النَّاسُ أَمْ نَسُوا وَالَّذِي بَعَثَ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَقِّ لَقَدْ خَرَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا تَرَكَ التَّلْبِيَةَ حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏إِلَّا أَنْ يَخْلِطَهَا بِتَكْبِيرٍ أَوْ تَهْلِيلٍ ‏","","",""],[3766,3766,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا عَلَى ‏ ‏قُرَيْشٍ ‏ ‏غَيْرَ يَوْمٍ وَاحِدٍ فَإِنَّهُ كَانَ ‏ ‏يُصَلِّي وَرَهْطٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏جُلُوسٌ ‏ ‏وَسَلَى ‏ ‏جَزُورٍ ‏ ‏قَرِيبٌ مِنْهُ فَقَالُوا مَنْ يَأْخُذُ هَذَا ‏ ‏السَّلَى ‏ ‏فَيُلْقِيَهُ عَلَى ظَهْرِهِ قَالَ فَقَالَ ‏ ‏عُقْبَةُ بْنُ أَبِي مُعَيْطٍ ‏ ‏أَنَا فَأَخَذَهُ فَأَلْقَاهُ عَلَى ظَهْرِهِ فَلَمْ يَزَلْ سَاجِدًا حَتَّى جَاءَتْ ‏ ‏فَاطِمَةُ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهَا فَأَخَذَتْهُ عَنْ ظَهْرِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ عَلَيْكَ الْمَلَأَ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏اللَّهُمَّ عَلَيْكَ ‏ ‏بِعُتْبَةَ بْنِ رَبِيعَةَ ‏ ‏اللَّهُمَّ عَلَيْكَ ‏ ‏بِشَيْبَةَ بْنِ رَبِيعَةَ ‏ ‏اللَّهُمَّ عَلَيْكَ ‏ ‏بِأَبِي جَهْلِ بْنِ هِشَامٍ ‏ ‏اللَّهُمَّ عَلَيْكَ ‏ ‏بعُقْبَةَ بْنِ أَبِي مُعَيْطٍ ‏ ‏اللَّهُمَّ عَلَيْكَ ‏ ‏بِأُبَيِّ بْنِ خَلَفٍ ‏ ‏أَوْ ‏ ‏أُمَيَّةَ بْنِ خَلَفٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَلَقَدْ رَأَيْتُهُمْ قُتِلُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏جَمِيعًا ثُمَّ سُحِبُوا إِلَى ‏ ‏الْقَلِيبِ ‏ ‏غَيْرَ ‏ ‏أُبَيٍّ ‏ ‏أَوْ ‏ ‏أُمَيَّةَ ‏ ‏فَإِنَّهُ كَانَ رَجُلًا ضَخْمًا فَتَقَطَّعَ ‏","","",""],[3767,3767,"","","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بْنُ سَعْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ النَّاسِ قَرْنِي الَّذِينَ يَلُونِي ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ‏ ‏قَالَ وَلَا أَدْرِي أَقَالَ فِي الثَّالِثَةِ أَوْ فِي الرَّابِعَةِ ‏ ‏ثُمَّ يَخْلُفُ بَعْدَهُمْ خَلْفٌ تَسْبِقُ شَهَادَةُ أَحَدِهِمْ يَمِينَهُ وَيَمِينُهُ شَهَادَتَهُ ‏","","",""],[3768,3768,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ الْأُمَمَ عُرِضَتْ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَعُرِضَتْ عَلَيْهِ أُمَّتُهُ فَأَعْجَبَتْهُ كَثْرَتُهُمْ فَقِيلَ ‏ ‏إِنَّ مَعَ هَؤُلَاءِ سَبْعِينَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ ‏","","",""],[3769,3769,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏بَيْنَ كُلِّ ثَلَاثَةِ ‏ ‏نَفَرٍ ‏ ‏بَعِيرٌ وَكَانَ زَمِيلَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيٌّ ‏ ‏وَأَبُو لُبَابَةَ ‏ ‏قَالَ وَكَانَ إِذَا كَانَتْ ‏ ‏عُقْبَةُ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَا لَهُ ارْكَبْ حَتَّى نَمْشِيَ عَنْكَ فَيَقُولُ ‏ ‏مَا أَنْتُمَا بِأَقْوَى مِنِّي وَمَا أَنَا بِأَغْنَى عَنْ الْأَجْرِ مِنْكُمَا ‏","","",""],[3770,3770,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ ‏ ‏لَيْسَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏ذَكَرَهُ وَلَكِنْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏أَتَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْغَائِطَ ‏ ‏وَأَمَرَنِي أَنْ آتِيَهُ بِثَلَاثَةِ أَحْجَارٍ فَوَجَدْتُ حَجَرَيْنِ وَلَمْ أَجِدْ الثَّالِثَ فَأَخَذْتُ ‏ ‏رَوْثَةً ‏ ‏فَأَتَيْتُ بِهِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى ‏ ‏الرَّوْثَةَ ‏ ‏وَقَالَ هَذِهِ ‏ ‏رِكْسٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَذَكَرَ التَّشَهُّدَ تَشَهُّدَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْصُورٌ ‏ ‏وَالْأَعْمَشُ ‏ ‏وَحَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[3771,3771,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏وَعَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَتَاهُ فَقَالَ قَرَأْتُ ‏ ‏الْمُفَصَّلَ ‏ ‏فِي رَكْعَةٍ فَقَالَ بَلْ هَذَذْتَ كَهَذِّ الشِّعْرِ أَوْ ‏ ‏كَنَثْرِ ‏ ‏الدَّقَلِ ‏ ‏لَكِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَفْعَلْ كَمَا فَعَلْتَ كَانَ يَقْرَأُ ‏ ‏النُّظُرَ ‏ ‏الرَّحْمَنَ ‏ ‏وَالنَّجْمَ ‏ ‏فِي رَكْعَةٍ ‏ ‏قَالَ ‏ ‏فَذَكَرَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَشْرَ رَكَعَاتٍ بِعِشْرِينَ سُورَةً عَلَى تَأْلِيفِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏آخِرُهُنَّ ‏ ‏إِذَا الشَّمْسُ كُوِّرَتْ ‏ ‏وَالدُّخَانُ ‏","","",""],[3772,3772,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏بِجَمْعٍ ‏ ‏فَصَلَّى الصَّلَاتَيْنِ كُلَّ صَلَاةٍ وَحْدَهَا بِأَذَانٍ وَإِقَامَةٍ وَالْعَشَاءُ بَيْنَهُمَا وَصَلَّى الْفَجْرَ حِينَ سَطَعَ الْفَجْرُ ‏ ‏أَوْ قَالَ حِينَ قَالَ قَائِلٌ طَلَعَ الْفَجْرُ وَقَالَ قَائِلٌ لَمْ يَطْلُعْ ‏ ‏ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ هَاتَيْنِ الصَّلَاتَيْنِ تُحَوَّلَانِ عَنْ وَقْتِهِمَا فِي هَذَا الْمَكَانِ لَا يَقْدَمُ النَّاسُ جَمْعًا حَتَّى يُعْتِمُوا وَصَلَاةُ الْفَجْرِ هَذِهِ السَّاعَةُ ‏","","",""],[3773,3773,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَيَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَنَا الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ ‏","","",""],[3774,3774,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏مَا كَذَبَ الْفُؤَادُ مَا رَأَى ‏} ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِبْرِيلَ ‏ ‏فِي ‏ ‏حُلَّةٍ ‏ ‏مِنْ ‏ ‏رَفْرَفٍ ‏ ‏قَدْ مَلَأَ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏","","",""],[3775,3775,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَأَبُو أَحْمَدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏يُكَبِّرُ فِي كُلِّ رُكُوعٍ وَسُجُودٍ وَرَفْعٍ وَوَضْعٍ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏رِضْوَانُ اللَّهِ عَلَيْهِمَا وَيُسَلِّمُونَ عَلَى أَيْمَانِهِمْ وَشَمَائِلِهِمْ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ ‏","","",""],[3776,3776,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏وَأَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ فَقَالَ ‏ ‏الصَّلَاةُ لِوَقْتِهَا ‏ ‏وَبِرُّ ‏ ‏الْوَالِدَيْنِ وَالْجِهَادُ فِي سَبِيلِ اللَّهِ وَلَوْ اسْتَزَدْتُ لَزَادَنِي ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏اسْتَزَدْتُهُ ‏","","",""],[3777,3777,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏أَمْلَاهُ عَلَيَّ مِنْ كِتَابِهِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَلْقَمَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏عَلَّمَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ فَكَبَّرَ وَرَفَعَ يَدَيْهِ ثُمَّ رَكَعَ وَطَبَّقَ بَيْنَ يَدَيْهِ ‏ ‏وَجَعَلَهُمَا بَيْنَ رُكْبَتَيْهِ فَبَلَغَ ‏ ‏سَعْدًا ‏ ‏فَقَالَ صَدَقَ أَخِي قَدْ كُنَّا نَفْعَلُ ذَلِكَ ثُمَّ أُمِرْنَا بِهَذَا وَأَخَذَ بِرُكْبَتَيْهِ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏هَكَذَا ‏","","",""],[3778,3778,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً لَا أَدْرِي زَادَ أَوْ نَقَصَ ثُمَّ سَلَّمَ وَسَجَدَ سَجْدَتَيْنِ ‏","","",""],[3779,3779,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُدْرِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ ‏ ‏لَبَّى لَيْلَةَ ‏ ‏جَمْعٍ ‏ ‏ثُمَّ قَالَ هَاهُنَا رَأَيْتُ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏ ‏يُلَبِّي ‏","","",""],[3780,3780,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ اللَّهِ الْجَابِرِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْمَاجِدِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏فَذَكَرَ الْقِصَّةَ ‏ ‏وَأَنْشَأَ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ أَوَّلَ رَجُلٍ قُطِعَ فِي الْإِسْلَامِ ‏ ‏أَوْ مِنْ الْمُسْلِمِينَ ‏ ‏رَجُلٌ أُتِيَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ يَا رَسُولَ اللَّهِ إِنَّ هَذَا سَرَقَ فَكَأَنَّمَا أُسِفَّ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَادًا فَقَالَ بَعْضُهُمْ يَا رَسُولَ اللَّهِ ‏ ‏أَيْ يَقُولُ ‏ ‏مَا لَكَ فَقَالَ ‏ ‏وَمَا يَمْنَعُنِي وَأَنْتُمْ أَعْوَانُ الشَّيْطَانِ عَلَى صَاحِبِكُمْ وَاللَّهُ عَزَّ وَجَلَّ عَفُوٌّ يُحِبُّ الْعَفْوَ وَلَا يَنْبَغِي لِوَالِي أَمْرٍ أَنْ يُؤْتَى ‏ ‏بِحَدٍّ ‏ ‏إِلَّا أَقَامَهُ ثُمَّ قَرَأَ ‏ { ‏وَلْيَعْفُوا وَلْيَصْفَحُوا أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ وَاللَّهُ غَفُورٌ رَحِيمٌ ‏} ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَمْلَاهُ عَلَيْنَا ‏ ‏سُفْيَانُ ‏ ‏إِمْلَاءً ‏","","",""],[3781,3781,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى الْجَابِرِ ‏ ‏عَنْ ‏ ‏أَبِي الْمَاجِدِ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلْنَا نَبِيَّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السَّيْرِ بِالْجِنَازَةِ فَقَالَ ‏ ‏السَّيْرُ دُونَ ‏ ‏الْخَبَبِ ‏ ‏فَإِنْ يَكُ خَيْرًا تُعْجَلْ إِلَيْهِ وَإِنْ يَكُ سِوَى ذَلِكَ فَبُعْدًا لِأَهْلِ النَّارِ الْجِنَازَةُ مَتْبُوعَةٌ وَلَيْسَ مِنَّا مَنْ تَقَدَّمَهَا ‏","","",""],[3782,3782,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْأَقْمَرِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُنَا وَمَا تُقَامُ الصَّلَاةُ حَتَّى ‏ ‏تَكَامَلَ بِنَا الصُّفُوفُ فَمَنْ سَرَّهُ أَنْ يَلْقَى اللَّهَ عَزَّ وَجَلَّ غَدًا مُسْلِمًا فَلْيُحَافِظْ عَلَى هَؤُلَاءِ الصَّلَوَاتِ ‏ ‏الْمَكْتُوبَاتِ ‏ ‏حَيْثُ يُنَادَى بِهِنَّ فَإِنَّهُنَّ مِنْ سُنَنِ ‏ ‏الْهُدَى ‏ ‏وَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ شَرَعَ لِنَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُنَنَ ‏ ‏الْهُدَى ‏","","",""],[3783,3783,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَسَأَلْنَاهُ أَنْ يَقْرَأَ عَلَيْنَا ‏ ‏طسم ‏ ‏الْمِائَتَيْنِ فَقَالَ مَا هِيَ مَعِي وَلَكِنْ ‏ ‏عَلَيْكُمْ مَنْ أَخَذَهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَبَّابَ بْنَ الْأَرَتِّ ‏ ‏قَالَ فَأَتَيْنَا ‏ ‏خَبَّابَ بْنَ الْأَرَتِّ ‏ ‏فَقَرَأَهَا عَلَيْنَا ‏","","",""],[3784,3784,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُورَةً مِنْ الثَّلَاثِينَ مِنْ آلِ ‏ ‏حم ‏ ‏يَعْنِي ‏ ‏الْأَحْقَافَ ‏ ‏قَالَ وَكَانَتْ السُّورَةُ إِذَا كَانَتْ أَكْثَرَ مِنْ ثَلَاثِينَ آيَةً سُمِّيَتْ الثَّلَاثِينَ قَالَ فَرُحْتُ إِلَى الْمَسْجِدِ فَإِذَا رَجُلٌ يَقْرَؤُهَا عَلَى غَيْرِ مَا أَقْرَأَنِي فَقُلْتُ مَنْ أَقْرَأَكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقُلْتُ لِآخَرَ اقْرَأْهَا فَقَرَأَهَا عَلَى غَيْرِ قِرَاءَتِي وَقِرَاءَةِ صَاحِبِي فَانْطَلَقْتُ بِهِمَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ هَذَيْنِ يُخَالِفَانِي فِي الْقِرَاءَةِ قَالَ فَغَضِبَ ‏ ‏وَتَمَعَّرَ ‏ ‏وَجْهُهُ وَقَالَ ‏ ‏إِنَّمَا أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ ‏ ‏الِاخْتِلَافُ ‏ ‏قَالَ قَالَ ‏ ‏زِرٌّ ‏ ‏وَعِنْدَهُ رَجُلٌ ‏ ‏قَالَ فَقَالَ الرَّجُلُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُكُمْ أَنْ يَقْرَأَ كُلُّ رَجُلٍ مِنْكُمْ كَمَا أُقْرِئَ فَإِنَّمَا أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ ‏ ‏الِاخْتِلَافُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَلَا أَدْرِي أَشَيْئًا أَسَرَّهُ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ عَلِمَ مَا فِي نَفْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَالرَّجُلُ هُوَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِ ‏","","",""],[3785,3785,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏أَخْبَرَنَا ‏ ‏بَشِيرٌ أَبُو إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏سَيَّارٍ أَبِي الْحَكَمِ ‏ ‏عَنْ ‏ ‏طَارِقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ لَهُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏تَسْلِيمُ الرَّجُلِ عَلَيْكَ فَقُلْتَ صَدَقَ اللَّهُ وَرَسُولُهُ قَالَ فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ يَدَيْ السَّاعَةِ تَسْلِيمُ الْخَاصَّةِ ‏ ‏وَتَفْشُو التِّجَارَةُ حَتَّى تُعِينَ الْمَرْأَةُ زَوْجَهَا عَلَى ‏ ‏التِّجَارَةِ وَتُقْطَعُ ‏ ‏الْأَرْحَامُ ‏","","",""],[3786,3786,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ النَّهْشَلِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسًا الظُّهْرَ ‏ ‏أَوْ الْعَصْرَ ‏ ‏فَلَمَّا انْصَرَفَ قِيلَ لَهُ يَا رَسُولَ اللَّهِ أَزِيدَ فِي الصَّلَاةِ قَالَ لَا قَالُوا فَإِنَّكَ صَلَّيْتَ خَمْسًا قَالَ فَسَجَدَ سَجْدَتَيْ السَّهْوِ ثُمَّ قَالَ ‏ ‏إِنَّمَا أَنَا بَشَرٌ أَذْكُرُ كَمَا تَذْكُرُونَ وَأَنْسَى كَمَا تَنْسَوْنَ ‏","","",""],[3787,3787,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ حَيَّةً فَلَهُ سَبْعُ حَسَنَاتٍ وَمَنْ قَتَلَ ‏ ‏وَزَغًا ‏ ‏فَلَهُ حَسَنَةٌ وَمَنْ تَرَكَ حَيَّةً مَخَافَةَ عَاقِبَتِهَا فَلَيْسَ مِنَّا ‏","","",""],[3788,3788,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنْ ‏ ‏كُرْدُوسٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏مَرَّ الْمَلَأُ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ ‏ ‏خَبَّابٌ ‏ ‏وَصُهَيْبٌ ‏ ‏وَبِلَالٌ ‏ ‏وَعَمَّارٌ ‏ ‏فَقَالُوا يَا ‏ ‏مُحَمَّدُ ‏ ‏أَرَضِيتَ بِهَؤُلَاءِ فَنَزَلَ فِيهِمْ الْقُرْآنُ ‏ { ‏وَأَنْذِرْ بِهِ الَّذِينَ يَخَافُونَ أَنْ يُحْشَرُوا إِلَى رَبِّهِمْ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَاللَّهُ أَعْلَمُ بِالظَّالِمِينَ ‏}","","",""],[3789,3789,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَيْسَ لَنَا نِسَاءٌ فَقُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَسْتَخْصِي ‏ ‏فَنَهَانَا عَنْهُ ثُمَّ رُخِّصَ لَنَا بَعْدُ فِي أَنْ نَتَزَوَّجَ الْمَرْأَةَ بِالثَّوْبِ إِلَى ‏ ‏أَجَلٍ ‏ ‏ثُمَّ قَرَأَ ‏ ‏عَبْدُ اللَّهِ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُحَرِّمُوا طَيِّبَاتِ مَا أَحَلَّ اللَّهُ لَكُمْ وَلَا تَعْتَدُوا إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ ‏}","","",""],[3790,3790,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَحَدَّثْنَا لَيْلَةً عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ‏ ‏أَكْرَيْنَا ‏ ‏الْحَدِيثَ ثُمَّ رَجَعْنَا إِلَى أَهْلِنَا فَلَمَّا أَصْبَحْنَا ‏ ‏غَدَوْنَا ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ عُرِضَتْ عَلَيَّ الْأَنْبِيَاءُ بِأُمَمِهَا وَأَتْبَاعُهَا مِنْ أُمَمِهَا فَجَعَلَ النَّبِيُّ يَمُرُّ وَمَعَهُ الثَّلَاثَةُ مِنْ أُمَّتِهِ وَالنَّبِيُّ مَعَهُ ‏ ‏الْعِصَابَةُ ‏ ‏مِنْ أُمَّتِهِ وَالنَّبِيُّ مَعَهُ ‏ ‏النَّفَرُ ‏ ‏مِنْ أُمَّتِهِ وَالنَّبِيُّ مَعَهُ الرَّجُلُ مِنْ أُمَّتِهِ وَالنَّبِيُّ مَا مَعَهُ أَحَدٌ حَتَّى مَرَّ عَلَيَّ ‏ ‏مُوسَى بْنُ عِمْرَانَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏كَبْكَبَةٍ ‏ ‏مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَلَمَّا رَأَيْتُهُمْ أَعْجَبُونِي قُلْتُ يَا رَبِّ مَنْ هَؤُلَاءِ فَقَالَ ‏ ‏هَذَا أَخُوكَ ‏ ‏مُوسَى بْنُ عِمْرَانَ ‏ ‏وَمَنْ مَعَهُ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قُلْتُ يَا رَبِّ فَأَيْنَ أُمَّتِي قَالَ انْظُرْ عَنْ يَمِينِكَ فَإِذَا ‏ ‏الظِّرَابُ ‏ ‏ظِرَابُ ‏ ‏مَكَّةَ ‏ ‏قَدْ سُدَّ بِوُجُوهِ الرِّجَالِ قُلْتُ مَنْ هَؤُلَاءِ يَا رَبِّ قَالَ أُمَّتُكَ قُلْتُ رَضِيتُ رَبِّ قَالَ أَرَضِيتَ قُلْتُ نَعَمْ قَالَ انْظُرْ عَنْ يَسَارِكَ قَالَ فَنَظَرْتُ فَإِذَا ‏ ‏الْأُفُقُ ‏ ‏قَدْ سُدَّ بِوُجُوهِ الرِّجَالِ فَقَالَ رَضِيتَ قُلْتُ رَضِيتُ قِيلَ فَإِنَّ مَعَ هَؤُلَاءِ سَبْعِينَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ لَا حِسَابَ لَهُمْ ‏ ‏فَأَنْشَأَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ ‏ ‏أَحَدُ ‏ ‏بَنِي أَسَدِ بْنِ خُزَيْمَةَ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ اللَّهُمَّ اجْعَلْهُ مِنْهُمْ ثُمَّ ‏ ‏أَنْشَأُ ‏ ‏رَجُلٌ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏تَحَدَّثْنَا ذَاتَ لَيْلَةٍ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏و حَدَّثَنَا ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏تَحَدَّثْنَا عِنْدَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏والْعَلَاءِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏تَحَدَّثْنَا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ حَتَّى ‏ ‏أَكْرَيْنَا ‏ ‏الْحَدِيثَ فَذَكَرَهُ ‏","","",""],[3791,3791,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ يَعْنِي ابْنَ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ حَيَّةٍ ‏ ‏بِمِنًى ‏","","",""],[3792,3792,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَجْتَنِي سِوَاكًا مِنْ ‏ ‏الْأَرَاكِ ‏ ‏وَكَانَ دَقِيقَ السَّاقَيْنِ فَجَعَلَتْ الرِّيحُ ‏ ‏تَكْفَؤُهُ ‏ ‏فَضَحِكَ الْقَوْمُ مِنْهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّ تَضْحَكُونَ قَالُوا يَا نَبِيَّ اللَّهِ مِنْ دِقَّةِ سَاقَيْهِ فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَهُمَا أَثْقَلُ فِي الْمِيزَانِ مِنْ ‏ ‏أُحُدٍ ‏","","",""],[3793,3793,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُورَةَ ‏ ‏الْأَحْقَافِ ‏ ‏وَأَقْرَأَهَا رَجُلًا آخَرَ فَخَالَفَنِي فِي آيَةٍ فَقُلْتُ لَهُ مَنْ أَقْرَأَكَهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْتُهُ وَهُوَ فِي ‏ ‏نَفَرٍ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أَلَمْ تُقْرِئْنِي آيَةَ كَذَا وَكَذَا فَقَالَ بَلَى قَالَ قُلْتُ فَإِنَّ هَذَا يَزْعُمُ أَنَّكَ أَقْرَأْتَهَا إِيَّاهُ كَذَا وَكَذَا فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ الرَّجُلُ الَّذِي عِنْدَهُ ‏ ‏لِيَقْرَأْ كُلُّ رَجُلٍ مِنْكُمْ كَمَا سَمِعَ فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ ‏ ‏بِالِاخْتِلَافِ ‏ ‏قَالَ فَوَاللَّهِ مَا أَدْرِي أَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ بِذَلِكَ أَمْ هُوَ قَالَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعْنَاهُ وَقَالَ فَغَضِبَ ‏ ‏وَتَمَعَّرَ ‏ ‏وَجْهُهُ وَقَالَ إِنَّمَا أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ ‏ ‏الِاخْتِلَافُ ‏","","",""],[3794,3794,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏أَهْلِ الصُّفَّةِ ‏ ‏مَاتَ ‏ ‏فَوَجَدُوا فِي بُرْدَتِهِ دِينَارَيْنِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيَّتَانِ ‏","","",""],[3795,3795,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ النِّسَاءَ فَقَالَ لَهُنَّ ‏ ‏مَا مِنْكُنَّ امْرَأَةٌ يَمُوتُ لَهَا ثَلَاثَةٌ إِلَّا أَدْخَلَهَا اللَّهُ عَزَّ وَجَلَّ الْجَنَّةَ فَقَالَتْ أَجَلُّهُنَّ امْرَأَةً يَا رَسُولَ اللَّهِ وَصَاحِبَةُ ‏ ‏الِاثْنَيْنِ فِي الْجَنَّةِ قَالَ وَصَاحِبَةُ ‏ ‏الِاثْنَيْنِ فِي الْجَنَّةِ ‏","","",""],[3796,3796,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ أَبِي الْفُرَاتِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَعْيَنِ الْعَبْديِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏يَخْطُبُ ذَاتَ يَوْمٍ إِذْ مَرَّ بِحَيَّةٍ تَمْشِي عَلَى الْجِدَارِ فَقَطَعَ خُطْبَتَهُ ثُمَّ ضَرَبَهَا بِقَضِيبِهِ حَتَّى قَتَلَهَا ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَتَلَ حَيَّةً فَكَأَنَّمَا قَتَلَ رَجُلًا مُشْرِكًا قَدْ ‏ ‏حَلَّ ‏ ‏دَمُهُ ‏","","",""],[3797,3797,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي الْفُرَاتِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَعْيَنِ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْقِرَدَةِ وَالْخَنَازِيرِ أَهِيَ مِنْ نَسْلِ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏اللَّهَ عَزَّ وَجَلَّ لَمْ يَلْعَنْ قَوْمًا قَطُّ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فَمَسَخَهُمْ ‏ ‏فَيَكُونَ لَهُمْ نَسْلٌ حَتَّى يُهْلِكَهُمْ وَلَكِنَّ هَذَا خَلْقٌ كَانَ فَلَمَّا غَضِبَ اللَّهُ عَزَّ وَجَلَّ عَلَى ‏ ‏الْيَهُودِ ‏ ‏مَسَخَهُمْ ‏ ‏فَجَعَلَهُمْ مِثْلَهُمْ ‏","","",""],[3798,3798,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيُّ الْأَعْمَالِ أَحَبُّ إِلَى اللَّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏صَلِّ الصَّلَاةَ لِمَوَاقِيتِهَا قُلْتُ ثُمَّ أَيُّ قَالَ ‏ ‏بِرُّ ‏ ‏الْوَالِدَيْنِ قُلْتُ ثُمَّ أَيُّ قَالَ ثُمَّ الْجِهَادُ فِي سَبِيلِ اللَّهِ وَلَوْ اسْتَزَدْتُهُ لَزَادَنِي ‏","","",""],[3799,3799,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏وَاصِلٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَحْفَظُ ‏ ‏الْقَرَائِنَ ‏ ‏الَّتِي كَانَ ‏ ‏يَقْرُنُ ‏ ‏بَيْنَهُنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِي عَشْرَةَ سُورَةً مِنْ ‏ ‏الْمُفَصَّلِ ‏ ‏وَسُورَتَيْنِ مِنْ آلِ ‏ ‏حم ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏والْعَلَاءِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏تَحَدَّثْنَا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ حَتَّى ‏ ‏أَكْرَيْنَا ‏ ‏الْحَدِيثَ فَذَكَرَهُ ‏","","",""],[3800,3800,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عَشِيَّةَ الْجُمُعَةِ فِي الْمَسْجِدِ قَالَ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَحَدُنَا رَأَى مَعَ امْرَأَتِهِ رَجُلًا فَقَتَلَهُ قَتَلْتُمُوهُ وَإِنْ تَكَلَّمَ جَلَدْتُمُوهُ وَإِنْ سَكَتَ سَكَتَ عَلَى غَيْظٍ وَاللَّهِ لَئِنْ أَصْبَحْتُ صَالِحًا لَأَسْأَلَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَسَأَلَهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنْ أَحَدُنَا رَأَى مَعَ امْرَأَتِهِ رَجُلًا فَقَتَلَهُ قَتَلْتُمُوهُ وَإِنْ تَكَلَّمَ جَلَدْتُمُوهُ وَإِنْ سَكَتَ سَكَتَ عَلَى غَيْظٍ اللَّهُمَّ احْكُمْ قَالَ ‏ ‏فَأُنْزِلَتْ ‏ ‏آيَةُ اللِّعَانِ ‏ ‏قَالَ فَكَانَ ذَاكَ الرَّجُلُ أَوَّلَ مَنْ ابْتُلِيَ بِهِ ‏","","",""]];
